; ==========================================================================
; NEMESIS / GRADIUS - Konami (1986) - MSX1 - 128 KB MegaROM RC-742 (Konami4) - bank 00 (runs at 0x4000)
; ==========================================================================
; Generated by tools/mkasm.py from the actual control-flow trace.
; The comments come from tools/../src/*.notes and are anchored to an
; address, so they survive a re-trace.
; ==========================================================================

	org 0x04000


; ----------------------------------------------------------------------
; Labels that do not fall on any position emitted in the listing
; (targets outside the binary or inside an instruction).
; ----------------------------------------------------------------------
L_55F4:	equ 0x055f4

; ----------------------------------------------------------------------
; Addresses that only appear as a VALUE -in an `ld`, not in
; a jump-: pointers the code passes around, or numbers that
; happen to match an address. There is nothing to trace
; there; the equ exists so that the listing assembles.
; ----------------------------------------------------------------------
l56d1h:	equ 0x056d1
l5d1dh:	equ 0x05d1d

; ----------------------------------------------------------------------
; DATA header: MSX cartridge header: "AB", INIT = 0x4071, and the other three
;   entries (STATEMENT, DEVICE, TEXT) at zero, plus six reserved bytes.
;   0x4000..0x4010  (16 bytes)

; ----------------------------------------------------------------------
; CARTRIDGE HEADER
; ----------------------------------------------------------------------
DATA_header:
	defb 041h,042h	; 4000
	defw 04071h	; 4002  -> INIT
	defw 00000h	; 4004
	defw 00000h	; 4006
	defw 00000h	; 4008
	defb 000h,000h,000h,000h,000h,000h	; 400a

; ----------------------------------------------------------------------
; DATA gm_mark: The format mark: "CD" in ASCII (43 44). It is what the Game
;   Master looks for to know that this cartridge carries the long header; the
;   ones that carry the short one have "AB".
;   0x4010..0x4012  (2 bytes)
DATA_gm_mark:
	defb 043h,044h	; 4010

; ----------------------------------------------------------------------
; DATA gm_catalogue: The catalogue number in BCD, high byte first: 07 42, that
;   is RC-742, which is this cartridge's.
;   0x4012..0x4014  (2 bytes)
DATA_gm_catalogue:
	defb 007h,042h	; 4012

; ----------------------------------------------------------------------
; DATA gm_flags: 0x80: says which fields follow. They are read from bit 0 to 7
;   and a CLEAR bit means "this field is in the stream". Here the first seven
;   are present and the last one is missing, which is a callback through
;   CALSLT.
;   0x4014..0x4015  (1 bytes)
DATA_gm_flags:
	defb 080h	; 4014

; ----------------------------------------------------------------------
; DATA gm_fields: The seven fields the flags byte announces, in bit order:
;   0xE000 with the 0x04 that says when there is a live game (0x53B1 state_4
;   is where the stage starts); 0xE061 the stage with its modulo 8 (0x4129);
;   0xE060 the lives (0x53CC, in BCD); 0xE053 the high score; 0xE05B one
;   player's score and 0xE057 the other's (0x54AA picks between the two by bit
;   7 of 0xE002 and clears four bytes); and 0xE002, the game flags. That
;   0xE053 is the high score is something the cartridge itself tells us:
;   0x5558 clears from 0xE057 up to 0xEFFF when a game starts and those four
;   bytes are exactly the ones it leaves standing.
;   0x4015..0x4025  (16 bytes)
DATA_gm_fields:
	defb 000h,0e0h,004h	; 4015
	defb 061h,0e0h,008h	; 4018
	defw 0e060h	; 401b
	defw 0e053h	; 401d
	defw 0e05bh	; 401f
	defw 0e057h	; 4021
	defw 0e002h	; 4023

; ======================================================================
; CODE 0x4025..0x40fd  (216 bytes)
; ======================================================================


jump_to_intro:		; `jp 0x5A54`. It is the only place that enters the intro.
	jp intro		;4025

; ----------------------------------------------------------------------
; THE INTERRUPT
; ----------------------------------------------------------------------
interrupt:		; What INIT installs in the H.KEYI hook (0xFD9A). THE WHOLE GAME RUNS HERE.
	call 0013eh		;4028   ; BIOS RDVDP - Reads VDP status register | Reading the VDP status is what acknowledges the interrupt.
	di			;402b
	ld a,007h		;402c   ; Bank 7 at 0x8000 and bank 8 at 0xA000: the sound player and its data.
	ld (08000h),a		;402e   ; NOTE: the RAM copy at 0xF0F2 is NOT touched here, and that is why it can be undone afterwards.
	inc a			;4031
	ld (0a000h),a		;4032
	call 08063h		;4035   ; The sound runs entirely inside the interrupt.
	di			;4038
	ld a,(0f0f2h)		;4039   ; Whatever bank layout was there before is restored, reading it from the RAM copy.
	ld (08000h),a		;403c
	ld a,(0f0f3h)		;403f
	ld (0a000h),a		;4042
	ld hl,0e005h		;4045   ; Lock: if the game loop is already inside, this interrupt does not enter again.
	bit 0,(hl)		;4048
	jr nz,L_4058		;404a
	inc (hl)			;404c
	ei			;404d   ; The `ei` goes BEFORE the long work: the next interrupt can catch it halfway.
	call read_controller		;404e
	call state_machine		;4051   ; And here the real game starts.
	xor a			;4054
	ld (0e005h),a		;4055   ; The lock is released.
L_4058:
	ei			;4058
	ret			;4059
L_405A:
	jp 00047h		;405a   ; BIOS WRTVDP - Writes data in the VDP-register
add_a_to_hl:		; HL += A, with the carry done right. Called from 48 places.
	add a,l			;405d   ; HL = HL + A, fixing H if there is a carry.
	ld l,a			;405e
	ret nc			;405f
	inc h			;4060
	ret			;4061
add_a_to_de:		; DE += A. Called from 26 places.
	add a,e			;4062   ; DE = DE + A, the same.
	ld e,a			;4063
	ret nc			;4064
	inc d			;4065
	ret			;4066

; ----------------------------------------------------------------------
; THE KONAMI DISPATCHER
; ----------------------------------------------------------------------
dispatcher:		; Konami's dispatcher: the destination table goes RIGHT BEHIND the `call`.
	pop hl			;4067   ; `pop hl` takes the RETURN address, which is where the table starts.
	add a,a			;4068   ; Each entry is two bytes, so the index is doubled.
	call add_a_to_hl		;4069
	ld e,(hl)			;406c   ; The word in the table is the destination...
	inc hl			;406d
	ld d,(hl)			;406e
	ex de,hl			;406f
	jp (hl)			;4070   ; ...and here is the jump. The caller does NOT return: the table eats the return address.

; ----------------------------------------------------------------------
; INIT: THE BOOT
; ----------------------------------------------------------------------
INIT:		; What the BIOS calls at boot (the AB header says so at 0x4002).
	di			;4071
	im 1		;4072   ; Interrupt mode 1: the BIOS hook at 0x0038 ends up leading to 0xFD9A.
	di			;4074
	push hl			;4075
	ld hl,0f0f1h		;4076   ; 0xF0F1, 0xF0F2 and 0xF0F3 are the RAM copy of the three mapper registers.
	ld a,001h		;4079
	ld (06000h),a		;407b   ; Bank 1 at 0x6000...
	ld (hl),a			;407e
	inc a			;407f
	ld (08000h),a		;4080   ; ...bank 2 at 0x8000...
	inc hl			;4083
	ld (hl),a			;4084
	inc a			;4085
	ld (0a000h),a		;4086   ; ...and bank 3 at 0xA000. It is the default layout for the whole game.
	inc hl			;4089
	ld (hl),a			;408a
	pop hl			;408b
	ei			;408c
	call find_my_slot		;408d
	ld h,080h		;4090   ; H = 0x80: this cartridge is enabled in page 2, which is where 0x8000 and 0xA000 fall.
	call 00024h		;4092   ; BIOS ENASLT - Switches to specified slot and page definitively
	ld a,0c3h		;4095   ; `jp interrupt` is installed in the H.KEYI hook.
	ld (0fd9ah),a		;4097
	ld hl,interrupt		;409a
	ld (0fd9bh),hl		;409d
	ld sp,0f0f0h		;40a0   ; The stack, right below the mapper copy.
	ld hl,0e000h		;40a3   ; The 4 KB from 0xE000 to 0xEFFF are cleared, which is all of the game's memory.
	ld de,0e001h		;40a6
	ld bc,00fffh		;40a9
	ld (hl),000h		;40ac
	ldir		;40ae
	ld a,001h		;40b0
	ld (0e005h),a		;40b2   ; 0xE005 and 0xE006 to 1: the lock is set while booting.
	ld (0e006h),a		;40b5
	call start_machine		;40b8
	call find_other_cartridge		;40bb
	xor a			;40be
	ld (0e005h),a		;40bf
	call 0013eh		;40c2   ; BIOS RDVDP - Reads VDP status register
	di			;40c5   ; And once again the usual layout, now with the RAM clean
	push hl			;40c6
	ld hl,0f0f1h		;40c7
	ld a,001h		;40ca
	ld (06000h),a		;40cc
	ld (hl),a			;40cf
	inc a			;40d0
	ld (08000h),a		;40d1
	inc hl			;40d4
	ld (hl),a			;40d5
	inc a			;40d6
	ld (0a000h),a		;40d7
	inc hl			;40da
	ld (hl),a			;40db
	pop hl			;40dc
	ei			;40dd
	ei			;40de   ; INIT ends here, and stays here: the `jr $` next to it never exits.
L_40DF:
	jr L_40DF		;40df   ; And this is the end of INIT. There is no way out of here: the rest happens in the interrupt.
find_my_slot:		; Builds for ENASLT the slot number of this cartridge, reading RSLREG and SLTTBL.
	call 00138h		;40e1   ; BIOS RSLREG - Reads the primary slot register | RSLREG: the primary slot register
	rrca			;40e4   ; Two rotations: the slot of page 1, which is where this cartridge sits
	rrca			;40e5
	and 003h		;40e6
	ld c,a			;40e8
	ld b,000h		;40e9
	ld hl,0fcc1h		;40eb   ; 0xFCC1: the BIOS table that says whether that slot has subslots
	add hl,bc			;40ee
	ld a,(hl)			;40ef
	and 080h		;40f0   ; Bit 7 marks that it has them
	or c			;40f2
	ld c,a			;40f3
	inc hl			;40f4   ; Four more: the subslot of page 1
	inc hl			;40f5
	inc hl			;40f6
	inc hl			;40f7
	ld a,(hl)			;40f8
	and 00ch		;40f9
	or c			;40fb
	ret			;40fc

; ----------------------------------------------------------------------
; DATA dead_jump: Three bytes that are `jp 0x49E9`, that is, a shortcut to
;   request a sound. No instruction or table in the cartridge points to
;   0x40FD, and the one before ends in `ret`: it is dead code, and that is why
;   it is listed as bytes.
;   0x40fd..0x4100  (3 bytes)
jump_to_request_sound:		; `jp 0x49E9`. Nobody jumps here: it is dead code.
	defb 0c3h,0e9h,049h	; 40fd

; ======================================================================
; CODE 0x4100..0x418f  (143 bytes)
; ======================================================================



; ----------------------------------------------------------------------
; STARTING A GAME AND STARTING A STAGE
; ----------------------------------------------------------------------
start_game:		; Sets the score to zero, clears the 0x900 bytes of objects at 0xE300 and loads the stage data
	call load_stage_graphics		;4100   ; The score labels
	call write_captions		;4103
	xor a			;4106
	ld (0e071h),a		;4107   ; 0xE071 to zero: the power-up count
	ld hl,00000h		;410a   ; 0xE108, 0xE063 and 0xE127 to zero, two bytes at a time
	ld (0e108h),hl		;410d
	ld (0e063h),hl		;4110
	ld (0e127h),hl		;4113
	ld hl,0e300h		;4116   ; The 0x900 bytes of the object table, to zero
	ld de,0e301h		;4119
	ld bc,008ffh		;411c
	ld (hl),000h		;411f
	ldir		;4121
	call load_stage_data		;4123   ; And the data of whichever stage is due
	jp start_scroll		;4126
set_up_due_stage:		; Does NOT advance the stage: with 0xE061 at zero it sets it to one, and from the ninth onwards it replaces it with the one the table at 0x418F says; then it sets it up
	ld hl,0e061h		;4129
	ld a,(hl)			;412c   ; With the stage at zero, start with the first one
	and a			;412d
	jr nz,L_4132		;412e
	ld (hl),001h		;4130
L_4132:
	ld a,(hl)			;4132
	sub 009h		;4133   ; Below nine the stage is set up as it is
	jr c,start_stage		;4135
	ld de,0418fh		;4137   ; The table at 0x418F, indexed by the stage minus nine: it only has four entries
	call add_a_to_de		;413a
	ld a,(de)			;413d
	ld (0e061h),a		;413e
	xor a			;4141   ; And the power-up count and the stage counter, to zero
	ld (0e071h),a		;4142
	ld hl,00000h		;4145
	ld (0e063h),hl		;4148
start_stage:		; Clears the 0xE00 bytes at 0xE100, turns off the 128 sprites, loads the stage data and waits 0x3C frames
	call load_stage_graphics		;414b
	ld hl,0e100h		;414e   ; The 0xE00 bytes from 0xE100 onwards, to zero
	ld de,0e101h		;4151
	ld bc,00dffh		;4154
	ld (hl),000h		;4157
	ldir		;4159
	ld hl,0ec80h		;415b   ; 0xE0 in the 128 Ys of the sprite buffer: none is drawn
	ld de,0ec81h		;415e
	ld (hl),0e0h		;4161
	ld c,07fh		;4163
	ldir		;4165
	call load_stage_data		;4167
	call stage_difficulty		;416a
	ld bc,00010h		;416d   ; Sixteen bytes from 0x4193 to 0xE200
	ld de,0e200h		;4170
	ld hl,04193h		;4173
	ldir		;4176
	call flag_if_two_players		;4178
	ld a,03ch		;417b   ; 0x3C frames of waiting before starting
	ld (0e10fh),a		;417d
	jp start_scroll		;4180
flag_if_two_players:		; 0xE130 to one if 0xE06B is not zero
	ld a,(0e06bh)		;4183
	or a			;4186
	jr z,L_418B		;4187
	ld a,001h		;4189
L_418B:
	ld (0e130h),a		;418b
	ret			;418e

; ----------------------------------------------------------------------
; DATA stages_per_round: Only FOUR useful bytes, from 0x418F to 0x4192: 0x03,
;   0x04, 0x05 and 0x08. They are indexed by 0x4137 with `ld de,0x418F` +
;   0x4062 and the index is (0xE061 minus 9), so they say which stage comes
;   after 9, 10, 11 and 12. There is NO fifth entry: the byte at 0x4193 is
;   already the first of the SIXTEEN that 0x416D copies to 0xE200 (the record
;   the ship starts with).
;   0x418f..0x41a3  (20 bytes)
DATA_stages_per_round:
	defb 003h,004h,005h,008h	; 418f
	defb 001h,000h,000h,000h	; 4193
	defb 04ah,000h,050h,000h	; 4197
	defb 008h,000h,008h,000h	; 419b
	defb 002h,000h,000h,000h	; 419f

; ======================================================================
; CODE 0x41a3..0x4214  (113 bytes)
; ======================================================================


stage_difficulty:		; 0xE111 comes from the round times four plus the stage, capped at 0x0F; past the ninth, from 0xE066
	ld a,(0e061h)		;41a3
	cp 009h		;41a6   ; From the ninth onwards, the difficulty is set by 0xE066
	jr nc,L_41BC		;41a8
	dec a			;41aa
	ld b,a			;41ab
	ld a,(0e06ah)		;41ac   ; The round times four
	add a,a			;41af
	add a,a			;41b0
	add a,b			;41b1
	cp 00fh		;41b2   ; Capped at 0x0F
	jr c,L_41B8		;41b4
	ld a,00fh		;41b6
L_41B8:
	ld (0e111h),a		;41b8
	ret			;41bb
L_41BC:
	ld a,(0e066h)		;41bc
	ld (0e111h),a		;41bf
	ret			;41c2
load_stage_data:		; Six bytes from the table at 0x4499 to 0xE101 (where the map script starts and ends), and from the one at 0x4212 the checkpoint the counter is compared with
	ld a,(0e061h)		;41c3
	add a,a			;41c6   ; Times six: six bytes per stage
	ld c,a			;41c7
	add a,a			;41c8
	add a,c			;41c9
	ld hl,04499h		;41ca
	call add_a_to_hl		;41cd
	ld de,0e101h		;41d0   ; To 0xE101
	ld bc,00006h		;41d3
	ldir		;41d6
	ld a,(0e061h)		;41d8
	ld hl,04212h		;41db   ; The other table, the checkpoints one
	call get_word		;41de
	ld hl,(0e063h)		;41e1
	rst 20h			;41e4   ; DCOMPR: if you had already passed the checkpoint, it starts there; and if not, at 0x20
	jr nc,set_stage_counters		;41e5
	ld de,00020h		;41e7
set_stage_counters:		; Sets the stage's dozen counters to zero, 0xE062 to one and 0xE129 to 0x40
	ld (0e063h),de		;41ea   ; The distance the stage starts with
	xor a			;41ee
	ld (0e150h),a		;41ef
	ld (0e151h),a		;41f2
	ld (0e065h),a		;41f5
	ld (0e155h),a		;41f8
	ld (0e113h),a		;41fb
	ld (0e10ah),a		;41fe
	ld (0e044h),a		;4201
	ld (0e114h),a		;4204
	ld (0e126h),a		;4207
	inc a			;420a   ; 0xE062 to one
	ld (0e062h),a		;420b
	ld a,040h		;420e   ; 0xE129 starts at 0x40
	ld (0e129h),a		;4210
	ret			;4213

; ----------------------------------------------------------------------
; DATA checkpoints (part): ELEVEN words, from 0x4214 to 0x422A: the CHECKPOINT
;   of each stage. It is read by 0x41DB with `ld hl,0x4212` and 0x47AE, which
;   adds the stage TWICE, so stage 1 reads the one at 0x4214 and stage 11 the
;   one at 0x4228. When setting up the stage, 0x41E1 compares the distance
;   already covered with this number; if you had passed it, the stage restarts
;   right there, and if not, at 0x20. They are 0xF8, 0x100, 0xF2, 0x100,
;   0x100, 0x100, 0xF8, 0x100, 0x100, 0x100 and 0x100. NOTE: STAGE 12 RUNS OFF
;   THE TABLE. Its read lands at 0x422A, which are the first two bytes of the
;   `call 0x58BA` at 0x422A, and gives it 0xBACD = 47821; since the distance
;   never gets anywhere near that, stage 12 always starts at 0x20.
;   0x4214..0x422a  (22 bytes)  of 0x4212..0x422a (24 bytes)
DATA_checkpoints_4214:
	defw 000f8h,00100h	; 4214
	defw 000f2h,00100h	; 4218
	defw 00100h,00100h	; 421c
	defw 000f8h,00100h	; 4220
	defw 00100h,00100h	; 4224
	defw 00100h	; 4228

; ======================================================================
; CODE 0x422a..0x42b3  (137 bytes)
; ======================================================================



; ----------------------------------------------------------------------
; THE GRAPHICS OF EACH STAGE
; The cartridge does not store the screens already drawn: it stores
; compressed blocks in banks 4, 5 and 6, and when a stage starts it
; decompresses them into VRAM. With the graphics in place, 0x4348 ALSO
; makes the flipped characters: 0x43F2 reverses the bits of each byte
; (horizontal mirror) and 0x43C6 reverses the order of the eight bytes
; (vertical mirror). That way a drawing and its reflection take up a
; single block in the ROM.
; ----------------------------------------------------------------------
load_stage_graphics:		; Maps banks 4, 5 and 6, decompresses what is due for the stage and restores the usual layout
	call load_stage_font		;422a
	di			;422d   ; Banks 4, 5 and 6, which are the graphics ones
	push hl			;422e   ; Banks 4, 5 and 6, which are the graphics ones
	ld hl,0f0f1h		;422f
	ld a,004h		;4232
	ld (06000h),a		;4234
	ld (hl),a			;4237
	inc a			;4238
	ld (08000h),a		;4239
	inc hl			;423c
	ld (hl),a			;423d
	inc a			;423e
	ld (0a000h),a		;423f
	inc hl			;4242
	ld (hl),a			;4243
	pop hl			;4244
	ei			;4245
	call load_stage_characters		;4246
	ld hl,01800h		;4249   ; The block at 0x86BB to VRAM 0x1800: the sprite patterns
	ld de,086bbh		;424c
	call decompress		;424f
	ld a,(0e061h)		;4252   ; The stage times six: two groups of three bytes in the table at 0x42AD
	add a,a			;4255
	ld b,a			;4256
	add a,a			;4257
	add a,b			;4258
	ld hl,042adh		;4259
	call add_a_to_hl		;425c
	ld b,002h		;425f   ; Two blocks per stage
decompress_both_blocks:		; For each group: the source in DE and, in C, the character where it starts; the VRAM address comes from C times eight plus 0x1800
	push bc			;4261
	ld e,(hl)			;4262
	inc hl			;4263
	ld d,(hl)			;4264
	inc hl			;4265
	ld c,(hl)			;4266   ; The third byte is the character where it starts
	inc hl			;4267
	push hl			;4268
	ld l,c			;4269   ; Times eight: each character is eight bytes
	ld h,000h		;426a
	add hl,hl			;426c
	add hl,hl			;426d
	add hl,hl			;426e
	ld bc,01800h		;426f   ; And from VRAM 0x1800
	add hl,bc			;4272
	call decompress		;4273
	pop hl			;4276
	pop bc			;4277
	djnz decompress_both_blocks		;4278
	ld a,(0e061h)		;427a
	cp 005h		;427d   ; Stage 5 also gets the block at 0x8FCB at VRAM 0x1D00
	jr nz,L_428A		;427f
	ld hl,01d00h		;4281
	ld de,08fcbh		;4284
	call decompress		;4287
L_428A:
	ld a,(0f0f4h)		;428a   ; And with 0xF0F4 set, one more at 0x1800
	or a			;428d
	jr z,restore_usual_layout		;428e
	ld hl,01800h		;4290
	ld de,09963h		;4293
	call decompress		;4296
restore_usual_layout:		; Banks 1, 2 and 3 in their three slots, and the RAM copy up to date
	di			;4299   ; The usual layout is restored: banks 1, 2 and 3
	push hl			;429a
	ld hl,0f0f1h		;429b
	ld a,001h		;429e
	ld (06000h),a		;42a0   ; Bank 1 at 0x6000...
	ld (hl),a			;42a3
	inc a			;42a4
	ld (08000h),a		;42a5   ; ...bank 2 at 0x8000...
	inc hl			;42a8
	ld (hl),a			;42a9
	inc a			;42aa
	ld (0a000h),a		;42ab   ; ...and bank 3 at 0xA000
	inc hl			;42ae
	ld (hl),a			;42af
	pop hl			;42b0
	ei			;42b1
	ret			;42b2

; ----------------------------------------------------------------------
; DATA graphics_per_stage: Six bytes per stage: two groups of (source of the
;   compressed block, index of the character where it starts). The declared
;   base is 0x42AD (0x4259), which falls INSIDE the code: stage 0 does not
;   exist and the table really starts at stage 1. The sources point into bank
;   5.
;   0x42b3..0x42fb  (72 bytes)
DATA_graphics_per_stage:
	defb 04bh,08eh,0bch,08ch,08ah,0cch	; 42b3
	defb 04bh,08eh,0bch,08ch,08ah,0cch	; 42b9
	defb 01eh,08ch,0dch,0cah,08eh,0bch	; 42bf
	defb 0cah,08eh,0bch,08ch,08ah,0cch	; 42c5
	defb 0cah,08eh,0bch,038h,090h,0cch	; 42cb
	defb 0cah,08eh,0bch,08ch,08ah,0cch	; 42d1
	defb 027h,08dh,0dch,04bh,08eh,0bch	; 42d7
	defb 04bh,08eh,0bch,08ch,08ah,0cch	; 42dd
	defb 03eh,08fh,0e0h,0fbh,042h,0ffh	; 42e3
	defb 03eh,08fh,0e0h,0fbh,042h,0ffh	; 42e9
	defb 03eh,08fh,0e0h,0fbh,042h,0ffh	; 42ef
	defb 03eh,08fh,0e0h,0fbh,042h,0ffh	; 42f5

; ----------------------------------------------------------------------
; DATA empty_block: A single 0x00. It is a compressed stream that ends at its
;   first byte, and stages 9 to 12 use it as "there is no second block here".
;   0x42fb..0x42fc  (1 bytes)
DATA_empty_block:
	defb 000h	; 42fb

