walk_entries:		; Takes from the table in HL the list due for the stage and walks it
	ld a,(0e061h)		;433f
	call get_word		;4342
	push de			;4345
	pop ix		;4346
build_mirror:		; For each four-byte entry: unpacks it, flips it and uploads it to the thirds its bits say
