	and a			;434b
	ret z			;434c
	ld l,(ix+003h)		;434d   ; The fourth byte is the character; times eight, the bytes it takes up
	ld h,000h		;4350
	add hl,hl			;4352
	add hl,hl			;4353
	add hl,hl			;4354
	ld (0e101h),hl		;4355
	call download_character_to_ram		;4358
	ld a,(0e100h)		;435b   ; 0xE100 says which mirror it is
	and a			;435e
	push af			;435f
