	ld l,(ix+003h)		;4398   ; The character times eight, plus the third that is due
	ld h,000h		;439b
	add hl,hl			;439d
	add hl,hl			;439e
	add hl,hl			;439f
	add hl,de			;43a0
	push hl			;43a1
