	ld a,(de)			;43dd
	ld (hl),a			;43de
	ld a,c			;43df
	ld (de),a			;43e0
	inc hl			;43e1
	dec de			;43e2
	djnz swap_eight_bytes		;43e3
	inc hl			;43e5   ; Four more: the next character
	inc hl			;43e6
	inc hl			;43e7
	inc hl			;43e8
	ld a,00ch		;43e9   ; 0x0C: the next character, counting backwards
	call add_a_to_de		;43eb
	exx			;43ee
	djnz L_43D9		;43ef
	ret			;43f1
