	djnz L_43FB		;43fe
	ld (hl),a			;4400
	inc hl			;4401
	dec de			;4402   ; As many bytes as 0xE101 says
	ld a,d			;4403
	or e			;4404
	jr nz,L_43F9		;4405
	ret			;4407
upload_mirror:		; Bits 3, 4 and 5 of the second byte say which thirds the flipped character is uploaded to
