	bit 4,(ix+002h)		;4412   ; Bit 4: the middle one
	ld de,00800h		;4416
	call nz,upload_mirror_to_vram		;4419
	bit 5,(ix+002h)		;441c   ; And bit 5: the first one
	ld de,00000h		;4420
	ret z			;4423
upload_mirror_to_vram:		; The flipped character goes back to VRAM: the patterns from 0xE300 and the colours from 0xE700
