	ld h,000h		;4429
	add hl,hl			;442b   ; Times eight, plus the third that DE brings
	add hl,hl			;442c
	add hl,hl			;442d
	add hl,de			;442e
	push hl			;442f
	ld de,02000h		;4430   ; The patterns, 0x2000 higher
	add hl,de			;4433
	ld de,0e300h		;4434
	ld bc,(0e101h)		;4437   ; And as many bytes as 0xE101 says
	call dump_to_vram		;443b
	pop hl			;443e
	ld de,00000h		;443f   ; The colours go as they are, without the 0x2000
	add hl,de			;4442
	ld de,0e700h		;4443
	ld bc,(0e101h)		;4446
	call dump_to_vram		;444a
	pop ix		;444d
	ret			;444f
download_character_to_ram:		; The character to be flipped is brought from VRAM to 0xE300 and 0xE700: to make the mirror you have to read what was already uploaded
