; ----------------------------------------------------------------------
; THE PAUSE
; ----------------------------------------------------------------------
check_pause_key:		; With the game running, looks at bit 5 of keyboard row 6 and, when it is pressed, toggles between pause and play
	ld a,(0e002h)		;44e7   ; Bit 6 of 0xE002: only with the game running
	and 040h		;44ea
	jr z,game_frame		;44ec
	ld a,(0e1d0h)		;44ee   ; And with 0xE1D0 at zero
	and a			;44f1
	jr nz,game_frame		;44f2
	ld a,006h		;44f4
	call 00141h		;44f6   ; BIOS SNSMAT - Returns the value of the specified line from the keyboard matrix | SNSMAT of row 6; bit 5 is the GRAPH key
	cpl			;44f9   ; A cpl: on the keyboard a pressed key is a zero
	and 020h		;44fa
	ld hl,0e10ch		;44fc   ; 0xE10C keeps the previous state, to catch the new press
	ld c,(hl)			;44ff
	ld (hl),a			;4500
	xor c			;4501   ; What has changed and is set: it has just gone down
	and (hl)			;4502
	dec hl			;4503
	jr z,L_4518		;4504
	inc (hl)			;4506   ; 0xE10B counts the presses: even is play, odd is pause
	bit 0,(hl)		;4507
	ld de,00000h		;4509   ; In play, 0xE047 to zero
	jr z,L_4514		;450c
	ld de,00101h		;450e   ; And in pause, 0x0101
	call clear_typing_state		;4511
L_4514:
	ld (0e047h),de		;4514
L_4518:
	bit 0,(hl)		;4518   ; Only with the game paused are the keyboard cheats read
	jr z,game_frame		;451a
	call check_typed_keys		;451c
	ld a,(0e200h)		;451f   ; 0xE200 negative: the pause is handled elsewhere
	and a			;4522
	jp m,upload_sprites_rotating		;4523
	call 0998ch		;4526   ; Three routines from banks 2 and 3, with the game stopped
	call 09c90h		;4529
	call 0a17fh		;452c
	jp upload_sprites_rotating		;452f

; ----------------------------------------------------------------------
; ONE FRAME OF PLAY
; This is the game's shopping list: thirty-odd calls in a row, nearly all
; of them to banks 1, 2 and 3, and everything that happens in a frame is
; done in that order. There is no loop and no table: it is a strip of
; `call`s. Banks 11 and 12 (the pieces and the stage scripts) are slipped
; in the middle on purpose for a single call, and then 2 and 3 are
; restored.
; ----------------------------------------------------------------------
game_frame:		; The strip of calls that makes a whole frame: the scroll, the enemies, the shots, the collisions and the score
	ld a,(0e009h)		;4532   ; 0xE009 is copied to 0xE10D: the joystick, as it was left
	ld (0e10dh),a		;4535
	call upload_sprites_rotating		;4538
	call 06ccdh		;453b
	ld a,(0e1d0h)		;453e   ; With 0xE1D0 set there is an explosion in progress
	and a			;4541
	call nz,dispatch_ship_end		;4542
	ld a,(0e1d1h)		;4545   ; And with 0xE1D1 set, the frame is cut short here
	and a			;4548
	ret nz			;4549
	call 0b042h		;454a
	xor a			;454d
	ld (0e112h),a		;454e   ; 0xE112 to zero
	di			;4551   ; Banks 11 and 12: the pieces and the stage scripts
	ld a,00bh		;4552
	ld (08000h),a		;4554
	ld (0f0f2h),a		;4557   ; The RAM copy of the mapper is updated at the same time
	ei			;455a
	di			;455b
	ld a,00ch		;455c
	ld (0a000h),a		;455e
	ld (0f0f3h),a		;4561
	ei			;4564
	call scroll_map_one_column		;4565   ; And with them in place, the piece of screen that is due is built
	di			;4568   ; 2 and 3 restored, which are the usual ones
	ld a,002h		;4569
	ld (08000h),a		;456b
	ld (0f0f2h),a		;456e
	ei			;4571
	di			;4572
	ld a,003h		;4573
	ld (0a000h),a		;4575
	ld (0f0f3h),a		;4578
	ei			;457b
	call 0890bh		;457c
	call 08935h		;457f
	call 09955h		;4582
	call 0a068h		;4585
	call 09c41h		;4588
	call 09e14h		;458b
	call 09cc5h		;458e
	call 0a17fh		;4591
	call run_twelve_objects		;4594
	call 0a310h		;4597
	call 0aba3h		;459a
	call 065dch		;459d
	call release_what_is_due		;45a0
	call 090c1h		;45a3
	call run_background_objects		;45a6
	call 0b145h		;45a9
	call 062c1h		;45ac
	call 0616ah		;45af
	call 07c34h		;45b2
	call 070d6h		;45b5
	call 08ec4h		;45b8
	call 0760eh		;45bb
	call 09f81h		;45be
	call 068fbh		;45c1
	call 06936h		;45c4
	call 08fb0h		;45c7
	call 07c5ah		;45ca
	call 061afh		;45cd
	call 08ffeh		;45d0
	call 0b431h		;45d3
	call 071e8h		;45d6
	call 09f85h		;45d9
	call 06893h		;45dc
	call run_sprites		;45df
	call blink_two_characters		;45e2
	call upload_screen		;45e5
	call 06983h		;45e8
	ld a,(0e003h)		;45eb   ; One frame in eight
	and 007h		;45ee
	dec a			;45f0
	ret nz			;45f1
	jp draw_scores		;45f2   ; ...it is time to refresh the score
start_scroll:		; Moves the distance counter back 0x20 and leaves the screen pointer at 0xED00, with 0x20 steps to take
	xor a			;45f5
	ld (0ec04h),a		;45f6   ; 0xEC04 to zero
	ld hl,(0e063h)		;45f9   ; 0x20 less on the distance covered
	ld de,00020h		;45fc
	sbc hl,de		;45ff
	ld (0e063h),hl		;4601
	ld hl,0ed00h		;4604   ; 0xED00: where it starts reading the screen
	ld (0ec00h),hl		;4607
	ld b,020h		;460a   ; Thirty-two steps

; ----------------------------------------------------------------------
; THE SCROLL
; The stage map is not read from VRAM: it lives in RAM, at 0xED00, and it
; is twenty-two rows of thirty-two cells. On each scroll step, 0x469D
; SHIFTS IT ONE COLUMN TO THE LEFT with twenty-two `ldir`s of 0x1F bytes,
; and 0x46AE puts the new column in on the right, which comes from the
; stage script and from the 4x4-character pieces of bank 11.
; ----------------------------------------------------------------------
take_scroll_steps:		; B scroll steps; on each one it maps banks 11 and 12 to read the script, and then four more routines
	push bc			;460c
	di			;460d
	ld a,00bh		;460e   ; Banks 11 and 12: the pieces and the scripts
	ld (08000h),a		;4610
	ld (0f0f2h),a		;4613
	ei			;4616
	di			;4617
	ld a,00ch		;4618
	ld (0a000h),a		;461a
	ld (0f0f3h),a		;461d
	ei			;4620
	call read_new_column		;4621   ; With them in place the new column is read
	di			;4624
	ld a,002h		;4625   ; And 2 and 3 are restored
	ld (08000h),a		;4627
	ld (0f0f2h),a		;462a
	ei			;462d
	di			;462e
	ld a,003h		;462f
	ld (0a000h),a		;4631
	ld (0f0f3h),a		;4634
	ei			;4637
	call 090b5h		;4638
	call 062adh		;463b
	call 0aedfh		;463e
	call 0b845h		;4641
	ld hl,(0ec00h)		;4644   ; 0xEC00 moves forward one cell
	inc hl			;4647
	ld (0ec00h),hl		;4648
	ld hl,0ec04h		;464b   ; 0xEC04, eight points per step
	ld a,(hl)			;464e
	add a,008h		;464f
	ld (hl),a			;4651
	ld hl,(0e063h)		;4652   ; And the distance covered, one unit
	inc hl			;4655
	ld (0e063h),hl		;4656
	pop bc			;4659
	djnz take_scroll_steps		;465a
	ld hl,(0e063h)		;465c   ; On the way out the last step is given back: the loop overshoots by one
	dec hl			;465f
	ld (0e063h),hl		;4660
	ret			;4663
flag_not_due:		; 0xE107 to one: no new column comes in on this step
	ld a,001h		;4664
	ld (0e107h),a		;4666
	ret			;4669
scroll_map_one_column:		; If it is time to scroll, raises the distance and shifts the twenty-two rows at 0xED00 one cell to the left
	xor a			;466a
	ld (0e100h),a		;466b
	ld (0e107h),a		;466e
	ld de,(0e105h)		;4671   ; 0xE105 is how far the stage's scroll goes
	ld hl,(0e063h)		;4675
	rst 20h			;4678   ; DCOMPR: compares the distance with the limit
	jr nc,flag_not_due		;4679
	ld a,(0e1c0h)		;467b   ; 0xE1C0 sets the speed: at one, standing still
	dec a			;467e
	ret z			;467f
	dec a			;4680   ; At two, it shifts on every step
	jr z,L_468C		;4681
	ld de,0e062h		;4683   ; And otherwise, every other step, with the bit that rotates in 0xE062
	ld a,(de)			;4686
	rlca			;4687
	ld (de),a			;4688
	and 001h		;4689
	ret z			;468b
L_468C:
	inc hl			;468c   ; The distance goes up
	ld (0e063h),hl		;468d
	ld a,001h		;4690   ; 0xE100 to one: there is a new column on this step
	ld (0e100h),a		;4692
	ld hl,0ed01h		;4695   ; From 0xED01 to 0xED00: the whole map, one cell to the left
	ld de,0ed00h		;4698
	ld b,016h		;469b   ; Twenty-two rows
L_469D:
	push bc			;469d
	ld bc,0001fh		;469e   ; Thirty-one cells per row
	ldir		;46a1
	pop bc			;46a3
	inc hl			;46a4   ; And the leftover cell when jumping to the next row
	inc de			;46a5
	djnz L_469D		;46a6
	ld hl,0ed1fh		;46a8   ; 0xEC00 points to the right-hand column, the one to be filled
	ld (0ec00h),hl		;46ab
read_new_column:		; With the distance inside the range, takes from the stage script the piece that is due and leaves its address in 0xEC02
	ld hl,(0e063h)		;46ae   ; The distance covered...
	ld de,(0e103h)		;46b1   ; ...against the end of the range
	rst 20h			;46b5
	ccf			;46b6
	jr c,draw_star_column		;46b7
	ld de,(0e101h)		;46b9   ; And against where it starts
	and a			;46bd
	sbc hl,de		;46be
	jr c,draw_star_column		;46c0
	push hl			;46c2
	ld hl,097deh		;46c3   ; The script table at 0x97DE, indexed by the stage
	ld a,(0e061h)		;46c6
	call get_word		;46c9
	pop hl			;46cc
	ld a,l			;46cd
	srl h		;46ce   ; The distance divided by two: each piece is four cells wide
	rra			;46d0
	and 0feh		;46d1
	ld l,a			;46d3
	ld c,l			;46d4
	ld b,h			;46d5
	add hl,hl			;46d6   ; Times three and added: times six, which is what a row of the script takes up
	add hl,bc			;46d7
	add hl,de			;46d8
	ld (0ec02h),hl		;46d9   ; 0xEC02 keeps where the piece is
	ld hl,(0ec00h)		;46dc
	ld b,006h		;46df
insert_new_column:		; Copies into the right-hand column of the map the four cells due from the piece, jumping from row to row
	push bc			;46e1
	push hl			;46e2
	ld hl,(0ec02h)		;46e3   ; The script hands out piece numbers
	ld a,(hl)			;46e6
	inc hl			;46e7
	ld (0ec02h),hl		;46e8
	ld l,a			;46eb
	ld h,000h		;46ec
	add hl,hl			;46ee   ; Times sixteen: each piece is four by four characters
	add hl,hl			;46ef
	add hl,hl			;46f0
	add hl,hl			;46f1
	ld de,08ff0h		;46f2   ; Stages 5, 9, 10 and 12 use the other set of pieces, the one at 0x8FF0
	ld a,(0e061h)		;46f5
	cp 005h		;46f8
	jr z,L_470B		;46fa
	cp 009h		;46fc
	jr z,L_470B		;46fe
	cp 00ah		;4700
	jr z,L_470B		;4702
	cp 00ch		;4704
	jr z,L_470B		;4706
	ld de,08000h		;4708
L_470B:
	add hl,de			;470b
	ex de,hl			;470c
	ld a,(0e063h)		;470d   ; The two low bits of the distance: which of the four columns of the piece is due
	and 003h		;4710
	call add_a_to_de		;4712
	pop hl			;4715
	dec b			;4716
	ld bc,00020h		;4717   ; 0x20: from one map row to the one below
	jr z,half_piece		;471a
	ld a,(de)			;471c
	ld (hl),a			;471d
	add hl,bc			;471e
	inc de			;471f   ; And four bytes: the same column, one row further down the piece
	inc de			;4720
	inc de			;4721
	inc de			;4722
	ld a,(de)			;4723
	ld (hl),a			;4724
	add hl,bc			;4725
	inc de			;4726
	inc de			;4727
	inc de			;4728
	inc de			;4729
half_piece:		; The other two cells of the piece, when the column coming in is the second half
	ld a,(de)			;472a   ; The third byte of the piece
	ld (hl),a			;472b
	add hl,bc			;472c   ; Four bytes: the next row down in the piece
	inc de			;472d
	inc de			;472e
	inc de			;472f
	inc de			;4730
	ld a,(de)			;4731
	ld (hl),a			;4732
	add hl,bc			;4733   ; And 0x20: the next row down in the map
	pop bc			;4734
	djnz insert_new_column		;4735
	ret			;4737

; ----------------------------------------------------------------------
; THE STARS COME FROM THE R REGISTER
; When the stage has no script to read, the column coming in is sky: a
; single character lit on the row the table at 0x478E says, and the rest
; at zero. Which of the two star drawings goes in is decided by `ld a,r`,
; the Z80's refresh register, which counts on its own with every
; instruction. It is the closest thing to chance in the cartridge, and it
; is only used so that the stars do not all twinkle the same.
; ----------------------------------------------------------------------
draw_star_column:		; Fills the incoming column with zeros, except for one cell: the star, on the row the table at 0x478E says
	ld a,(0e063h)		;4738   ; The five low bits of the distance index the table
	and 01fh		;473b
	ld hl,0478eh		;473d
	call add_a_to_hl		;4740
	ld c,(hl)			;4743   ; C says which row the star falls on
	ld b,016h		;4744   ; Twenty-two rows
	ld de,00020h		;4746
	ld hl,(0ec00h)		;4749
L_474C:
	xor a			;474c
	dec c			;474d
	jr nz,L_4756		;474e
	ld a,r		;4750   ; The Z80's R register: the only thing that stands in for chance here
	and 001h		;4752
	add a,0f6h		;4754   ; 0xF6 or 0xF7: the two star drawings
L_4756:
	ld (hl),a			;4756
	add hl,de			;4757
	djnz L_474C		;4758
	ret			;475a
blink_two_characters:		; Every two frames turns the patterns at 0x27B0 and 0x27B8 off or on, in the three thirds
	ld a,(0e003h)		;475b   ; Two bits of the frame counter: four steps
	and 006h		;475e
	ld hl,04786h		;4760   ; The mask table at 0x4786
	ld e,a			;4763
	ld d,000h		;4764
	add hl,de			;4766
	ld c,(hl)			;4767
	inc hl			;4768
	ld b,(hl)			;4769
	ld hl,027b0h		;476a   ; The character at VRAM 0x27B0...
	call L_4774		;476d
	ld c,b			;4770
	ld hl,027b8h		;4771   ; ...and the one at 0x27B8
L_4774:
	ld a,(0e062h)		;4774   ; 0xE062, the bit that rotates
	and c			;4777
	call 0004dh		;4778   ; BIOS WRTVRM - Writes data in VRAM
	ld de,00800h		;477b   ; The three thirds, 0x800 apart
	add hl,de			;477e
	call 0004dh		;477f   ; BIOS WRTVRM - Writes data in VRAM
	add hl,de			;4782
	jp 0004dh		;4783   ; BIOS WRTVRM - Writes data in VRAM

; ----------------------------------------------------------------------
; DATA blink: Four words that 0x4760 indexes with (0xE003 AND 6).
;   0x4786..0x478e  (8 bytes)
DATA_blink:
	defw 000ffh,0ffffh	; 4786
	defw 0ff00h,0ffffh	; 478a

; ----------------------------------------------------------------------
; DATA star_row: Thirty-two bytes that 0x473D indexes with (0xE063 AND 0x1F):
;   which of the twenty-two rows the star of the incoming column falls on. The
;   values go from 1 to 0x14, so it always falls inside.
;   0x478e..0x47ae  (32 bytes)
DATA_star_row:
	defb 002h,00fh,005h,013h,00ah,001h,00dh,006h,011h,008h,00bh,002h,010h,007h,00dh,005h,012h,00ch,002h,012h,009h,00eh,014h,011h,002h,005h,00dh,00ah,013h,006h,00fh,009h	; 478e  ................................

; ======================================================================
; CODE 0x47ae..0x4956  (424 bytes)
; ======================================================================


get_word:		; DE = the word at HL + 2*A. Called from 36 places.
	add a,a			;47ae   ; Times two: the table is made of words
	ld e,a			;47af
	ld d,000h		;47b0
	add hl,de			;47b2
	ld e,(hl)			;47b3
	inc hl			;47b4
	ld d,(hl)			;47b5
	ret			;47b6
run_sprites:		; Four passes: two routines from banks 1 and 3, the second group of objects and the sprite engine
	call 06199h		;47b7
	call 0a27fh		;47ba
	call build_second_group		;47bd
	jp build_sprites		;47c0
upload_sprites:		; Sends the 128 bytes at 0xEC80 out of the VDP data port with `outi`: 32 sprites of four bytes, in one go.
	ld hl,0ec80h		;47c3
	ld b,080h		;47c6
L_47C8:
	outi		;47c8   ; `outi` with B=0x80: the 128 bytes of the attribute table without going through the BIOS.
	jp nz,L_47C8		;47ca
	ret			;47cd

; ----------------------------------------------------------------------
; SPRITE PRIORITY, WHICH KEEPS ROTATING
; The MSX only draws four sprites per line, and the ones that drop out
; are always the last ones in the table. So that the one that disappears
; is not always the same, this routine does not upload the buffer in one
; go: it uploads it in THIRTY-TWO pieces of four bytes, starting each
; frame at a different place (0xE17F goes up by 0x1C and wraps at 0x7C)
; and stepping 0x0C at a time. That way each object lands in a different
; slot of the attribute table every frame, and the flicker is shared out
; among all of them.
; ----------------------------------------------------------------------
upload_sprites_rotating:		; Uploads the buffer to the attribute table starting each frame at a different place: that way the flicker is shared out
	ld hl,03b00h		;47ce   ; The sprite attribute table, at VRAM 0x3B00
	call set_vram_write		;47d1
	exx			;47d4
	ld a,(0e200h)		;47d5   ; With 0xE200 at 0xFF it is uploaded as it is, without rotating
	inc a			;47d8
	jr z,upload_sprites		;47d9
	ld hl,0e17fh		;47db
	ld a,(hl)			;47de
	add a,01ch		;47df   ; 0x1C more each frame, wrapping at 0x7C
	and 07ch		;47e1
	ld (hl),a			;47e3
	ld e,a			;47e4
	ld d,020h		;47e5   ; Thirty-two entries of four bytes
L_47E7:
	ld a,e			;47e7
	ld hl,0ec80h		;47e8
	add a,l			;47eb
	ld l,a			;47ec
	ld b,004h		;47ed
L_47EF:
	outi		;47ef   ; The four bytes of an entry, through the data port
	jp nz,L_47EF		;47f1
	ld a,e			;47f4
	add a,00ch		;47f5   ; And on to the entry 0x0C further on, wrapping around
	and 07ch		;47f7
	ld e,a			;47f9
	dec d			;47fa
	jr nz,L_47E7		;47fb
	ret			;47fd
upload_screen:		; The 704 bytes of the map at 0xED00 to the name table, with `outi` and without going through the BIOS
	ld hl,03800h		;47fe   ; The name table, at VRAM 0x3800
	call set_vram_write		;4801
	exx			;4804
	ld hl,0ed00h		;4805
	ld b,000h		;4808   ; B at zero: 256 bytes in one go
L_480A:
	outi		;480a
	jp nz,L_480A		;480c
L_480F:
	outi		;480f
	jp nz,L_480F		;4811
	ld b,0c0h		;4814   ; And the last 192: twenty-two rows of thirty-two
L_4816:
	outi		;4816
	jp nz,L_4816		;4818
	ret			;481b
build_second_group:		; The other ten objects, the ones at 0xE500, to the buffer at 0xECD8
	ld ix,0e500h		;481c   ; 0xE500: the second group of objects
	ld de,0ecd8h		;4820
	ld b,00ah		;4823   ; Ten objects
	jr walk_objects		;4825

; ----------------------------------------------------------------------
; THE SPRITE ENGINE: FROM THE OBJECTS AT 0xE300 TO THE ATTRIBUTE TABLE
; ----------------------------------------------------------------------
build_sprites:		; With banks 4/5/6 in place, walks twelve objects at 0xE300 (32 bytes each) and builds their sprite attribute in 0xECA8.
	di			;4827
	push hl			;4828
	ld hl,0f0f1h		;4829
	ld a,004h		;482c   ; Banks 4/5/6: the sprite engine needs to read the shapes in bank 5.
	ld (06000h),a		;482e
	ld (hl),a			;4831
	inc a			;4832
	ld (08000h),a		;4833
	inc hl			;4836
	ld (hl),a			;4837
	inc a			;4838
	ld (0a000h),a		;4839
	inc hl			;483c
	ld (hl),a			;483d
	pop hl			;483e
	ei			;483f
	ld ix,0e300h		;4840   ; 0xE300 is the object table, and 0xECA8 the attribute buffer
	ld de,0eca8h		;4844
	ld b,00ch		;4847
walk_objects:		; For each live slot, sets its attribute entry; and if it is hidden, takes it off the screen
	push bc			;4849
	ld a,(ix+000h)		;484a   ; With the first byte at zero, the slot is empty
	and a			;484d
	jr z,empty_slot		;484e
	cp 019h		;4850   ; And 0x19 also counts as empty
	jr z,empty_slot		;4852
	ld a,(ix+00bh)		;4854   ; Byte 11 says whether the object is hidden
	and a			;4857
	push af			;4858
	call z,set_attribute		;4859
	pop af			;485c
	call nz,hide_sprite		;485d
next_object:		; Moves on to the next object and, once the twelve are done, restores the usual layout
	exx			;4860
	ld de,00020h		;4861   ; Thirty-two bytes per object
	add ix,de		;4864
	exx			;4866
	pop bc			;4867
	djnz walk_objects		;4868   ; The twelve
	di			;486a   ; Banks 1, 2 and 3 again
	push hl			;486b   ; The usual layout: banks 1, 2 and 3
	ld hl,0f0f1h		;486c
	ld a,001h		;486f
	ld (06000h),a		;4871
	ld (hl),a			;4874
	inc a			;4875
	ld (08000h),a		;4876
	inc hl			;4879
	ld (hl),a			;487a
	inc a			;487b
	ld (0a000h),a		;487c
	inc hl			;487f
	ld (hl),a			;4880
	pop hl			;4881
	ei			;4882
	ret			;4883
empty_slot:		; 0xE0 in the Y: the VDP draws nothing below that height
	ld a,0e0h		;4884   ; 0xE0 in the Y and the other three fields untouched
	ld (de),a			;4886
	inc e			;4887
	inc e			;4888
	inc e			;4889
	inc e			;488a
	jr next_object		;488b
set_attribute:		; Copies to the buffer the object's Y, X, pattern number and colour (IX+4, IX+6, IX+0C, IX+0D).
	ld a,(ix+004h)		;488d   ; Byte 4 of the object is the Y...
	ld (de),a			;4890
	inc e			;4891
	ld a,(ix+006h)		;4892   ; ...6 the X...
	ld (de),a			;4895
	inc e			;4896
	ld a,(ix+00ch)		;4897   ; ...12 the pattern number...
	ld (de),a			;489a
	inc e			;489b
	ld a,(ix+00dh)		;489c   ; ...and 13 the colour
	ld (de),a			;489f
	inc e			;48a0
	ret			;48a1
hide_sprite:		; Puts 0xE0 in the Y, which is the height at which the VDP does not draw it, and drops the object if it goes off the bottom or the right.
	ld a,0e0h		;48a2
	ld (de),a			;48a4
	inc e			;48a5
	inc e			;48a6
	inc e			;48a7
	inc e			;48a8
	ld a,(ix+004h)		;48a9   ; Below Y 0xB8 and X 0xF8 it carries on; otherwise, it is not drawn with characters
	cp 0b8h		;48ac
	ret nc			;48ae
	ld a,(ix+006h)		;48af
	cp 0f8h		;48b2
	ret nc			;48b4
	exx			;48b5
	ld l,(ix+01eh)		;48b6   ; Bytes 30 and 31 say which screen cell it falls on
	ld h,(ix+01fh)		;48b9
	ld a,(ix+00bh)		;48bc   ; Byte 11: if it is one it is four characters, and if not, two
	dec a			;48bf
	jr nz,two_characters		;48c0
	ex de,hl			;48c2
two_by_two:		; Takes the object's four characters from the table at 0x91D1 and writes them to the name table in two rows, 0x1E apart.
	ld a,(ix+00ch)		;48c3   ; The pattern number times four: four characters per drawing
	add a,a			;48c6
	ld l,a			;48c7
	ld h,000h		;48c8
	add hl,hl			;48ca
	ld bc,091d1h		;48cb
	add hl,bc			;48ce
	ldi		;48cf   ; The top two...
	ldi		;48d1
	ld a,01eh		;48d3   ; ...and 0x1E further on, the bottom two, which is the next row
	add a,e			;48d5
	ld e,a			;48d6
	jr nc,L_48DA		;48d7
	inc d			;48d9
L_48DA:
	ldi		;48da
	ldi		;48dc
	exx			;48de
	ret			;48df
two_characters:		; Objects that are not four characters are painted with two in a row, and byte 11 says which one they start at
	ld c,0a1h		;48e0   ; Byte 11 at two: characters 0xA1 and 0xA2
	dec a			;48e2
	jr z,L_48F1		;48e3
	ld c,0bfh		;48e5   ; At three: 0xBF and 0xC0
	dec a			;48e7
	jr z,L_48F1		;48e8
	ld c,058h		;48ea   ; At four: 0x58 and 0x59
	dec a			;48ec
	jr z,L_48F1		;48ed
	ld c,060h		;48ef   ; And otherwise, 0x60 and 0x61
L_48F1:
	ld (hl),c			;48f1   ; The second character goes right after the first
	inc hl			;48f2
	inc c			;48f3
	ld (hl),c			;48f4
	exx			;48f5
	ret			;48f6
clear_rectangle:		; B cells wide by C high, to zero, clipping whatever goes off the right
	call clip_right		;48f7
	ld e,b			;48fa
L_48FB:
	push hl			;48fb
	ld b,e			;48fc
	xor a			;48fd   ; Zero: the empty cell
L_48FE:
	ld (hl),a			;48fe
	inc hl			;48ff
	djnz L_48FE		;4900
	pop hl			;4902
	ld a,020h		;4903   ; 0x20: the row below
	call add_a_to_hl		;4905
	dec c			;4908
	jr nz,L_48FB		;4909
	ret			;490b
copy_rectangle:		; The same but copying from DE: B wide by C high, skipping in the source whatever was clipped
	push bc			;490c
	call clip_right		;490d
	pop af			;4910
	sub b			;4911   ; What was clipped, to skip it in the source too
	exx			;4912
	ld c,a			;4913
	exx			;4914
L_4915:
	push hl			;4915
	push bc			;4916
copy_row:		; B bytes from DE to HL: one row of the rectangle
	ld a,(de)			;4917   ; Byte by byte
	ld (hl),a			;4918
	inc hl			;4919
	inc de			;491a
	djnz copy_row		;491b
	pop bc			;491d
	pop hl			;491e
	ld a,020h		;491f   ; 0x20: the map row below
	call add_a_to_hl		;4921
	exx			;4924
	ld a,c			;4925
	exx			;4926
	call add_a_to_de		;4927
	dec c			;492a
	jr nz,L_4915		;492b
	ret			;492d
clip_right:		; If the rectangle goes off the row, takes the leftover cells off B
	call cell_to_ram_address		;492e
	ld a,l			;4931
	and 01fh		;4932   ; Which column it falls on
	add a,b			;4934
	sub 020h		;4935   ; And how far past thirty-two it goes
	ret c			;4937
	neg		;4938   ; B keeps what fits
	add a,b			;493a
	ld b,a			;493b
	ret			;493c
clear_screen:		; Calls 0x55AA and fills the 768 bytes of the name table (VRAM 0x3800) with zeros using FILVRM.
	call remove_sprites_from_screen		;493d
	ld hl,03800h		;4940   ; The 768 cells of the name table
	ld bc,00300h		;4943
	xor a			;4946
	jp 00056h		;4947   ; BIOS FILVRM - Fills VRAM with value
set_vram_write:		; SETWRT, and the VDP data port is saved in C'.
	ex af,af'			;494a
	call 00053h		;494b   ; BIOS SETWRT - Enables VDP to write
	exx			;494e
	ld a,(00007h)		;494f   ; 0x0007 holds this machine's VDP data port
	ld c,a			;4952
	exx			;4953
	ex af,af'			;4954
	ret			;4955

; ----------------------------------------------------------------------
; DATA dead_vram_read: Ten bytes that are `call SETRD / exx / ld a,(0x0006) /
;   ld c,a / exx / ret`: the twin of 0x494A for READING from VRAM. Nobody
;   calls it.
;   0x4956..0x4960  (10 bytes)
set_vram_read:		; SETRD, and the read port is saved in C'. Nobody calls it: it is the dead twin of 0x494A.
	defb 0cdh,050h,000h,0d9h,03ah,006h,000h,04fh,0d9h,0c9h	; 4956  .P..:..O..

; ======================================================================
; CODE 0x4960..0x4aca  (362 bytes)
; ======================================================================


dump_to_vram:		; LDIRVM with DE and HL swapped.
	ex de,hl			;4960
	jp 0005ch		;4961   ; BIOS LDIRVM - Block transfers to VRAM from memory
dump_three_thirds:		; Three LDIRVMs in a row, adding 0x800 each time: the three thirds of the screen.
	exx			;4964
	ld b,003h		;4965   ; Three thirds
L_4967:
	exx			;4967   ; One third at a time
	push bc			;4968
	push de			;4969
	call dump_to_vram		;496a
	ld de,00800h		;496d   ; 0x800: the next third
	add hl,de			;4970
	pop de			;4971
	pop bc			;4972
	exx			;4973
