explosion_step_0:		; Raises the counter at 0xE1D3 by 0x40 and, past Y 0xF0, clears the screen and turns the sprites off
	ld hl,(0e1d3h)		;4ade
	ld de,00040h		;4ae1   ; 0x40 more each frame
	add hl,de			;4ae4
	ld (0e1d3h),hl		;4ae5
	ld hl,00800h		;4ae8   ; 0x0800 in 0xE008
	ld (0e008h),hl		;4aeb
