	call release_shrapnel		;4b60
	call move_shrapnel		;4b63
	call animate_shrapnel		;4b66
	call upload_shrapnel_to_buffer		;4b69
	ld a,(0e1d5h)		;4b6c   ; 0xE1D5 goes down elsewhere; until it reaches zero, it does not go on
	or a			;4b6f
	ret nz			;4b70
	ld a,010h		;4b71   ; 0x10 frames per step of the drawing
	ld (0e1d2h),a		;4b73
	xor a			;4b76
	ld (0e1d9h),a		;4b77
	ld a,03bh		;4b7a   ; Sound 0x3B
	call check_if_sound		;4b7c
	jp next_submode		;4b7f
explosion_step_3:		; Every 0x10 frames swaps the 4x4 drawing for the next one at 0x6340; at the third, erases it and waits 0x40 frames
