	ld (0e1d2h),a		;4bf7
L_4BFA:
	ld a,(0e1d9h)		;4bfa
draw_meter:		; Takes from 0xE1D9 the lit cell of the power-up meter and writes its drawing with 0x4998.
	ld hl,04edah		;4bfd   ; 0xE1D9 says which cell of the meter is lit.
	call get_word		;4c00
