	ld (0e1d2h),a		;4c0b
	jp next_submode		;4c0e

; ----------------------------------------------------------------------
; DATA speeds (part): Six bytes that 0x4BF0 indexes with 0x4062 and stores in
;   0xE1D2: 0x28, 0x28, 0x10, 0x0C, 0x08, 0x04.
;   0x4c11..0x4c16  (5 bytes)  of 0x4c10..0x4c16 (6 bytes)
DATA_speeds_4C11:
	defb 028h,010h,00ch,008h,004h	; 4c11

; ======================================================================
; CODE 0x4c16..0x4d3e  (296 bytes)
; ======================================================================


explosion_step_5:		; Waits the frames in 0xE1D2 and then requests screen piece 0
	call pick_border_colour		;4c16
	ld hl,0e1d2h		;4c19
	dec (hl)			;4c1c
	ret nz			;4c1d
	ld b,000h		;4c1e   ; Black border
	call set_border_colour		;4c20
	ld a,028h		;4c23   ; And another 0x28 frames
	ld (0e1d2h),a		;4c25
	jp next_submode		;4c28

; ----------------------------------------------------------------------
; THE CARTRIDGE CHECKS WHICH COUNTRY THE MACHINE IS FROM
; At the end of a whole loop a message is written, and which one comes out
; depends on which loop it is: GOOD, NICE, FINE and GREAT for the first
; four. On the fifth, the cartridge reads 0x002B of the BIOS (the low
; nibble gives the machine's character set, and at zero it is Japanese)
; and splits: on a Japanese machine YOROKONDE ITADAKEMASHITAKA comes out,
; and on any other, CONGRATULATIONS. Both messages are in the ROM, one
; next to the other.
; ----------------------------------------------------------------------
explosion_step_6:		; Clears the screen, raises the loop number in 0xE070 wrapping at five, and writes the message that is due
	call clear_screen		;4c2b
	call load_scoreboard		;4c2e
	ld hl,0e070h		;4c31   ; 0xE070 is the loop: five and back to zero
	ld c,(hl)			;4c34
	ld a,c			;4c35
	inc a			;4c36
	cp 005h		;4c37
	jr c,L_4C3C		;4c39
	xor a			;4c3b
L_4C3C:
	ld (hl),a			;4c3c
	ld a,c			;4c3d
	cp 004h		;4c3e   ; Only on the fifth loop is the machine checked
	jr nz,L_4C50		;4c40
	ld a,(0002bh)		;4c42   ; The low nibble of 0x002B: the character set. At zero, Japanese
	and 00fh		;4c45
	ld a,004h		;4c47
	jr z,L_4C50		;4c49
	ld hl,0502eh		;4c4b   ; On any other machine, CONGRATULATIONS
	jr L_4C57		;4c4e
L_4C50:
	ld hl,04feah		;4c50   ; And otherwise, the message for the loop: GOOD, NICE, FINE, GREAT or the Japanese one
	call get_word		;4c53
	ex de,hl			;4c56
L_4C57:
	call start_slow_message		;4c57
	ld a,0a9h		;4c5a   ; Sound 0xA9
	call check_if_sound		;4c5c
	jp next_submode		;4c5f
explosion_step_7:		; When the message is done, leaves 0x6001 in 0xE044 and writes the one at 0x5040
	call write_one_letter		;4c62
	ret nz			;4c65
	ld hl,06001h		;4c66   ; 0x6001 in 0xE044 and 0xE045
	ld (0e044h),hl		;4c69
	xor a			;4c6c
	ld (0e046h),a		;4c6d   ; 0xE046 to zero
	ld hl,05040h		;4c70   ; And the message at 0x5040
	call start_slow_message		;4c73
	jp next_submode		;4c76
explosion_step_8:		; When it is done, gives away 500 points
	call write_one_letter		;4c79
	ret nz			;4c7c
	ld de,00500h		;4c7d   ; 0x0500 in BCD; the message at 0x5040 announces it as BONUS 50000 POINTS
	call add_to_score		;4c80
	jp next_submode		;4c83
explosion_step_9:		; Waits for the channel to go quiet, clears the screen and leaves both scripts pointing to 0x504A
	ld a,(0e012h)		;4c86   ; Until 0xE012 goes quiet, it does not go on
	and a			;4c89
	ret nz			;4c8a
	call clear_screen		;4c8b
	ld a,001h		;4c8e
	ld (0e150h),a		;4c90   ; 0xE150 to one
	ld de,0504ah		;4c93   ; 0x504A: the script both lists start with
	ld a,e			;4c96
	ld (0e204h),a		;4c97
	ld a,d			;4c9a
	ld (0e206h),a		;4c9b
	ld hl,0e224h		;4c9e   ; The two pointer tables, the one at 0xE224...
	call point_all_slots		;4ca1
	ld hl,0e244h		;4ca4   ; ...and the one at 0xE244
	call point_all_slots		;4ca7
	ld hl,0e300h		;4caa   ; And the 0x180 bytes of objects, to zero
	ld de,0e301h		;4cad
	ld bc,0017fh		;4cb0
	ld (hl),000h		;4cb3
	ldir		;4cb5
	ret			;4cb7
point_all_slots:		; Leaves the same pointer in the first slot and in the eight behind it
	ld (hl),e			;4cb8
	inc l			;4cb9
	inc l			;4cba
	ld (hl),d			;4cbb
	ld bc,0000ah		;4cbc   ; Ten bytes: the next slot
	add hl,bc			;4cbf
	ld b,008h		;4cc0   ; Eight more slots, now two bytes apart
L_4CC2:
	ld (hl),e			;4cc2   ; The eight two-byte slots
	inc l			;4cc3
	ld (hl),d			;4cc4
	inc l			;4cc5
	djnz L_4CC2		;4cc6
	ret			;4cc8

; ----------------------------------------------------------------------
; THE EXPLOSION SHRAPNEL, AND THE R REGISTER AGAIN
; When the ship blows up, a piece of shrapnel comes out every three frames,
; and all the chance in it comes from the Z80's R REGISTER, the memory
; refresh one, read four times in a row: one of its bits picks between the
; two drawings, another four pick one of the sixteen directions in the
; table at 0x4D3E, and the last two reads add a pinch to the X and to the
; Y so that two pieces with the same direction do not travel stuck
; together.
; In this mode, 0xE300 is NOT the usual object table: it is thirty-two
; slots of sixteen bytes.
; ----------------------------------------------------------------------
release_shrapnel:		; Every three frames releases a piece of shrapnel in the first free slot, with drawing, direction and push taken from the R register
	ld hl,0e1d7h		;4cc9   ; 0xE1D7: one piece every three frames
	dec (hl)			;4ccc
	ret nz			;4ccd
	ld (hl),003h		;4cce
	ld hl,(0e1d5h)		;4cd0   ; 0xE1D5 is what is left of the explosion
	ld a,l			;4cd3
	or h			;4cd4
	ret z			;4cd5
	dec hl			;4cd6
	ld (0e1d5h),hl		;4cd7
	ld a,r		;4cda   ; The R register: one bit to pick between the two drawings
	rra			;4cdc
	ld c,001h		;4cdd
	jr nc,L_4CE2		;4cdf
	inc c			;4ce1
L_4CE2:
	ld hl,0e300h		;4ce2   ; The thirty-two shrapnel slots
	ld b,020h		;4ce5
	xor a			;4ce7
	ld de,00010h		;4ce8   ; Sixteen bytes per slot
L_4CEB:
	cp (hl)			;4ceb   ; The first one that is at zero
	jr z,build_shrapnel_piece		;4cec
	add hl,de			;4cee
	djnz L_4CEB		;4cef
	ret			;4cf1
build_shrapnel_piece:		; Fills the slot: drawing, Y 0x38, X 0x80, and the direction it gets from the R register
	ld (hl),c			;4cf2
	inc l			;4cf3
	ld (hl),000h		;4cf4
	inc l			;4cf6
	inc l			;4cf7
	ld (hl),038h		;4cf8   ; The starting Y, 0x38
	inc l			;4cfa
	inc l			;4cfb
	ld (hl),080h		;4cfc   ; And the X, 0x80: the centre
	inc l			;4cfe
	ld a,r		;4cff   ; The R register again: four bits, one of the sixteen directions
	and 00fh		;4d01
	add a,a			;4d03   ; Times four: two words per direction
	add a,a			;4d04
	push hl			;4d05
	ld hl,04d3eh		;4d06
	call add_a_to_hl		;4d09
	ld e,(hl)			;4d0c
	inc hl			;4d0d
	ld d,(hl)			;4d0e
	inc hl			;4d0f
	ld a,(hl)			;4d10
	inc hl			;4d11
	ld b,(hl)			;4d12
	pop hl			;4d13
	dec c			;4d14   ; With the other drawing, the speed is halved
	ld c,a			;4d15
	jr z,L_4D20		;4d16
	sra d		;4d18   ; Shifting with the sign: it works for the negative directions
	rr e		;4d1a
	sra b		;4d1c
	rr c		;4d1e
L_4D20:
	ld a,r		;4d20   ; And the R register once more, to scatter the X...
	call add_a_to_de		;4d22
	ld (hl),e			;4d25
	inc l			;4d26
	ld (hl),d			;4d27
	ld a,r		;4d28   ; ...and once more for the Y
	ld e,c			;4d2a
	ld d,b			;4d2b
	call add_a_to_de		;4d2c
	inc l			;4d2f
	ld (hl),e			;4d30
	inc l			;4d31
	ld (hl),d			;4d32
	inc l			;4d33
	ld (hl),02ch		;4d34   ; 0x2C and 0x07: the pattern and the colour
	inc l			;4d36
	ld (hl),007h		;4d37
	ld hl,0e1d8h		;4d39   ; 0xE1D8 keeps count of the live pieces
	inc (hl)			;4d3c
	ret			;4d3d

; ----------------------------------------------------------------------
; DATA shrapnel_directions: Sixteen directions, two words each: the X step and
;   the Y step, in 8.8 fixed point (0x0200 is two points per frame). They are
;   indexed by 0x4D06 with four bits of the R register times four. They are
;   the sixteen directions of the compass rose, with their signs.
;   0x4d3e..0x4d7e  (64 bytes)
DATA_shrapnel_directions:
	defw 00000h,00200h	; 4d3e
	defw 000c4h,001d9h	; 4d42
	defw 0016ah,0016ah	; 4d46
	defw 001d9h,000c4h	; 4d4a
	defw 00200h,00000h	; 4d4e
	defw 001d9h,0ff3ch	; 4d52
	defw 0016ah,0fe96h	; 4d56
	defw 000c4h,0fe27h	; 4d5a
	defw 00000h,0fe00h	; 4d5e
	defw 0ff3ch,0fe27h	; 4d62
	defw 0fe96h,0fe96h	; 4d66
	defw 0fe27h,0ff3ch	; 4d6a
	defw 0fe00h,00000h	; 4d6e
	defw 0fe27h,000c4h	; 4d72
	defw 0fe96h,0016ah	; 4d76
	defw 0ff3ch,001d9h	; 4d7a

; ======================================================================
; CODE 0x4d7e..0x4e3b  (189 bytes)
; ======================================================================


move_shrapnel:		; Walks the thirty-two sixteen-byte slots and adds its speed to each piece; any that goes off the screen is turned off
	ld ix,0e300h		;4d7e
	ld b,020h		;4d82
L_4D84:
	ld a,(ix+000h)		;4d84   ; The slot at zero is free
	and a			;4d87
	jr z,L_4DBE		;4d88
	ld a,(ix+002h)		;4d8a   ; The 16-bit X plus its speed
	add a,(ix+006h)		;4d8d
	ld (ix+002h),a		;4d90
	ld a,(ix+003h)		;4d93
	adc a,(ix+007h)		;4d96
	cp 0c0h		;4d99   ; Past X 0xC0, the piece is gone
	jr nc,L_4DB6		;4d9b
	ld (ix+003h),a		;4d9d
	ld a,(ix+004h)		;4da0   ; And the same with the Y
	add a,(ix+008h)		;4da3
	ld (ix+004h),a		;4da6
	ld a,(ix+005h)		;4da9
	adc a,(ix+009h)		;4dac
	ld (ix+005h),a		;4daf
	cp 0f8h		;4db2   ; And the bottom limit, 0xF8
	jr c,L_4DBE		;4db4
L_4DB6:
	ld (ix+000h),000h		;4db6   ; The slot is freed...
	ld hl,0e1d8h		;4dba   ; ...and the count of live pieces goes down
	dec (hl)			;4dbd
L_4DBE:
	ld de,00010h		;4dbe   ; Sixteen bytes: the next slot
	add ix,de		;4dc1
	djnz L_4D84		;4dc3
	ret			;4dc5
upload_shrapnel_to_buffer:		; The thirty-two slots to the attribute buffer: the Y, the X, the pattern and the colour; a free slot goes to 0xE0
	ld ix,0e300h		;4dc6
	ld hl,0ec80h		;4dca
	ld b,020h		;4dcd
L_4DCF:
	ld c,(ix+003h)		;4dcf   ; Byte 3 is the Y
	ld a,(ix+000h)		;4dd2
	and a			;4dd5
	jr nz,L_4DDA		;4dd6
	ld c,0e0h		;4dd8   ; With the slot free, 0xE0: off the screen
L_4DDA:
	ld (hl),c			;4dda
	inc hl			;4ddb
	ld a,(ix+005h)		;4ddc   ; Byte 5 is the X
	ld (hl),a			;4ddf
	inc hl			;4de0
	ld a,(ix+00ah)		;4de1   ; And bytes 10 and 11, the pattern and the colour
	ld (hl),a			;4de4
	inc hl			;4de5
	ld a,(ix+00bh)		;4de6
	ld (hl),a			;4de9
	inc hl			;4dea
	ld de,00010h		;4deb   ; Sixteen bytes: the next slot
	add ix,de		;4dee
	djnz L_4DCF		;4df0
	ret			;4df2
animate_shrapnel:		; Raises each piece's counter and changes its pattern depending on how many frames it has been in the air
	ld b,020h		;4df3
	ld ix,0e300h		;4df5
L_4DF9:
	ld a,(ix+000h)		;4df9
	and a			;4dfc
	jr z,L_4E0B		;4dfd
	inc (ix+001h)		;4dff   ; One more frame for that piece
	dec a			;4e02   ; The first drawing has four phases; the other, two
	push af			;4e03
	call z,four_phases		;4e04
	pop af			;4e07
	call nz,two_phases		;4e08
L_4E0B:
	ld de,00010h		;4e0b
	add ix,de		;4e0e
	djnz L_4DF9		;4e10
	ret			;4e12
four_phases:		; Changes pattern at 0x0C, 0x18 and 0x24 frames: 0x2C, 0x30, 0x34 and 0x38
	ld a,(ix+001h)		;4e13   ; The frames the piece has been in the air
	ld c,02ch		;4e16   ; Below 0x0C, the first pattern
	cp 00ch		;4e18
	jr c,L_4E2A		;4e1a
	ld c,030h		;4e1c
	cp 018h		;4e1e   ; And then 0x30, 0x34 and 0x38
	jr c,L_4E2A		;4e20
	ld c,034h		;4e22
	cp 024h		;4e24
	jr c,L_4E2A		;4e26
	ld c,038h		;4e28
L_4E2A:
	ld (ix+00ah),c		;4e2a
	ret			;4e2d
two_phases:		; The other drawing only changes once, at 0x60 frames
	ld a,(ix+001h)		;4e2e   ; The frames the piece has been in the air
	ld c,02ch		;4e31
	cp 060h		;4e33
	jr c,L_4E2A		;4e35
	ld c,030h		;4e37
	jr L_4E2A		;4e39

; ----------------------------------------------------------------------
; DATA unreachable_code: Eighty-three bytes that disassemble as code (they
;   start with `ld a,(0xE1D2) / dec a / ld hl,0x4E82`) but that no path
;   reaches: the instruction before ends in `ret` and no instruction or table
;   in the cartridge points to 0x4E3B. They are listed as bytes so as not to
;   claim they are live code.
;   0x4e3b..0x4e8e  (83 bytes)
DATA_unreachable_code:
	defb 03ah,0d2h,0e1h,03dh,021h,082h,04eh,028h,011h,021h,076h,04eh,0feh,009h,038h,00ah	; 4e3b  :..=!.N(.!vN..8.
	defb 021h,06ah,04eh,0feh,013h,038h,003h,021h,05eh,04eh,011h,080h,0ech,001h,00ch,000h	; 4e4b  !jN..8.!^N......
	defb 0edh,0b0h,0c9h,040h,060h,000h,004h,040h,070h,004h,005h,040h,080h,024h,006h,040h	; 4e5b  ...@`..@p..@.$.@
	defb 060h,00ch,004h,040h,070h,010h,004h,040h,080h,028h,006h,040h,070h,018h,006h,040h	; 4e6b  `..@p..@.(.@p..@
	defb 070h,01ch,005h,0e0h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h	; 4e7b  p...............
	defb 000h,000h,000h	; 4e8b

; ======================================================================
; CODE 0x4e8e..0x4eda  (76 bytes)
; ======================================================================


pick_border_colour:		; A bit of 0xE1D2 picks between colour 3 and colour 9 for the border
	ld a,(0e1d2h)		;4e8e   ; A bit of 0xE1D2
	rra			;4e91
	rra			;4e92
	ld b,003h		;4e93
	jr c,L_4E99		;4e95
	ld b,009h		;4e97
L_4E99:
	jp set_border_colour		;4e99
start_slow_message:		; Stores the VRAM cell in 0xE1DB and the text in 0xE1DD: the message is going to be written letter by letter
	ld e,(hl)			;4e9c   ; The first two bytes are the cell
	inc hl			;4e9d
	ld d,(hl)			;4e9e
	inc hl			;4e9f
	ld (0e1dbh),de		;4ea0   ; The cell in 0xE1DB and the text in 0xE1DD
	ld (0e1ddh),hl		;4ea4
	ld a,001h		;4ea7   ; 0xE1DA to one: the first letter goes in straight away
	ld (0e1dah),a		;4ea9
	ret			;4eac
write_one_letter:		; Every six frames writes ONE letter of the message; 0xFF ends it and 0xFE continues it at another cell
	ld hl,0e1dah		;4ead   ; 0xE1DA: one letter every six frames
	dec (hl)			;4eb0
	ret nz			;4eb1
	ld (hl),006h		;4eb2
	ld hl,(0e1dbh)		;4eb4   ; How far the cell has got and how far the text has got
	ld de,(0e1ddh)		;4eb7
	ld a,(de)			;4ebb
	cp 0ffh		;4ebc   ; 0xFF: the message is complete
	ret z			;4ebe
	cp 0feh		;4ebf   ; And 0xFE: it carries on at another cell
	jr nz,L_4ECB		;4ec1
	inc de			;4ec3
	ex de,hl			;4ec4
	ld e,(hl)			;4ec5
	inc hl			;4ec6
	ld d,(hl)			;4ec7
	ex de,hl			;4ec8
	inc de			;4ec9
	ld a,(de)			;4eca
L_4ECB:
	inc de			;4ecb
	ld (0e1ddh),de		;4ecc
	call 0004dh		;4ed0   ; BIOS WRTVRM - Writes data in VRAM | The letter, to VRAM
	inc hl			;4ed3
	ld (0e1dbh),hl		;4ed4
	or 0ffh		;4ed7   ; Exits with 0xFF: there is still message left
	ret			;4ed9

; ----------------------------------------------------------------------
; DATA meter_table: Six words (0x4EE6, 0x4EEB, 0x4EF4, 0x4F08, 0x4F2B, 0x4F63)
;   that 0x4BFD indexes with 0xE1D9, the lit cell of the power-up meter. They
;   are NOT routines: they are the six drawings of the meter, and 0x4BFD ends
;   in `jp 0x4998`, which is the one that writes characters.
;   0x4eda..0x4ee6  (12 bytes)
DATA_meter_table:
	defw 04ee6h,04eebh	; 4eda  -> DATA_meter_drawings 0x4eeb
	defw 04ef4h,04f08h	; 4ede
	defw 04f2bh,04f63h	; 4ee2

; ----------------------------------------------------------------------
; DATA meter_drawings: The six drawings the table above points to, in the
;   0x4998 format: two bytes of VRAM address, followed by the characters (0xFE
;   = another address follows, 0xFF = end). They are counted, not estimated:
;   the six measure 5, 9, 20, 35, 56 and 79 bytes and fit exactly from 0x4EE6
;   to 0x4FB1. They write to the name table around 0x38EA-0x390E, which is the
;   meter's row.
;   0x4ee6..0x4fb2  (204 bytes)
DATA_meter_drawings:
	defb 0efh,038h,0a1h,0a2h,0ffh,0cfh,038h,0a3h,0feh,0efh,038h,0a4h,0a5h,0ffh,0ceh,038h	; 4ee6  .8....8...8....8
	defb 000h,0a6h,0a7h,000h,0feh,0eeh,038h,0a8h,0a9h,0aah,0abh,0feh,00eh,039h,000h,0ach	; 4ef6  ......8......9..
	defb 0adh,0ffh,0cch,038h,000h,000h,000h,0aeh,0feh,0ech,038h,000h,000h,000h,0afh,0b0h	; 4f06  ...8......8.....
	defb 000h,000h,0feh,00ch,039h,0b1h,0b2h,0b3h,0b4h,0b5h,0b6h,0b7h,0feh,02ch,039h,000h	; 4f16  ....9........,9.
	defb 000h,000h,0b8h,0b9h,0ffh,0cbh,038h,000h,000h,000h,000h,0bah,000h,000h,000h,0feh	; 4f26  ......8.........
	defb 0ebh,038h,000h,000h,000h,000h,0bbh,0bch,000h,000h,000h,0feh,00bh,039h,0bdh,0beh	; 4f36  .8...........9..
	defb 0bfh,0c0h,0c1h,0c2h,0c3h,0bfh,0c4h,0feh,02bh,039h,000h,0c5h,0c6h,0c7h,0c8h,0c9h	; 4f46  ........+9......
	defb 0cah,0cbh,0cch,0feh,04bh,039h,000h,000h,000h,000h,0cdh,0ceh,0ffh,0cah,038h,000h	; 4f56  ....K9........8.
	defb 000h,000h,000h,000h,0cfh,000h,000h,000h,0feh,0eah,038h,000h,000h,000h,000h,000h	; 4f66  ..........8.....
	defb 0d0h,000h,000h,000h,000h,0feh,00ah,039h,000h,000h,000h,000h,000h,0d1h,0d2h,000h	; 4f76  .......9........
	defb 000h,000h,000h,0feh,02ah,039h,0d3h,0d4h,000h,0d5h,0d6h,0d7h,0d8h,0d9h,0dah,000h	; 4f86  ....*9..........
	defb 0dbh,0dch,0feh,04ah,039h,000h,0ddh,0deh,0dfh,0e0h,0e1h,0e2h,0e3h,0e4h,0e5h,0e6h	; 4f96  ...J9...........
	defb 0feh,06ah,039h,000h,000h,000h,000h,0e7h,0e8h,0e9h,0eah,0ffh	; 4fa6  .j9.........

; ----------------------------------------------------------------------
; DATA four_by_four_drawing: Four rows of four characters (0xEB to 0xF8) at
;   row 5 and column 14, in the 0x4998 format: a drawing made of characters in
;   the middle of the screen. Requested by 0x4B39.
;   0x4fb2..0x4fce  (28 bytes)
DATA_four_by_four_drawing:
	defb 0aeh,038h,000h,0ebh,0ech,000h,0feh	; 4fb2
	defb 0ceh,038h,0edh,0eeh,0efh,0f0h,0feh	; 4fb9
	defb 0eeh,038h,0f1h,0f2h,0f3h,0f4h,0feh	; 4fc0
	defb 00eh,039h,0f5h,0f6h,0f7h,0f8h,0ffh	; 4fc7

; ----------------------------------------------------------------------
; DATA erase_drawing: The same drawing but with zeros, that is, the erasing.
;   Requested by 0x4BC1.
;   0x4fce..0x4fea  (28 bytes)
DATA_erase_drawing:
	defb 0aeh,038h,000h,000h,000h,000h,0feh	; 4fce
	defb 0ceh,038h,000h,000h,000h,000h,0feh	; 4fd5
	defb 0eeh,038h,000h,000h,000h,000h,0feh	; 4fdc
	defb 00eh,039h,000h,000h,000h,000h,0ffh	; 4fe3

; ----------------------------------------------------------------------
; DATA tables_of_4C4B: What 0x4C50 (0x4FEA), 0x4C4B (0x502E), 0x4C70 (0x5040)
;   and 0x4C93 (0x504A) read.
;   0x4fea..0x505a  (112 bytes)
DATA_tables_of_4C4B:
	defb 0f4h,04fh,0fbh,04fh,002h,050h,009h,050h,011h,050h,00eh,039h,027h,02fh,02fh,024h	; 4fea  .O.O.P.P.P.9'//$
	defb 0ffh,00eh,039h,02eh,029h,023h,025h,0ffh,00eh,039h,026h,029h,02eh,025h,0ffh,00dh	; 4ffa  ..9.)#%..9&).%..
	defb 039h,027h,032h,025h,021h,034h,0ffh,002h,039h,039h,02fh,032h,02fh,02bh,02fh,02eh	; 500a  9'2%!4..99/2/+/.
	defb 024h,025h,000h,029h,034h,021h,024h,021h,02bh,025h,02dh,021h,033h,028h,029h,034h	; 501a  $%.)4!$!+%-!3()4
	defb 021h,02bh,021h,0ffh,008h,039h,023h,02fh,02eh,027h,032h,021h,034h,035h,02ch,021h	; 502a  !+!..9#/.'2!45,!
	defb 034h,029h,02fh,02eh,033h,0ffh,062h,039h,000h,000h,000h,000h,000h,022h,02fh,02eh	; 503a  4)/.3.b9....."/.
	defb 035h,033h,000h,015h,010h,010h,010h,010h,000h,030h,02fh,029h,02eh,034h,033h,0ffh	; 504a  53.......0/).43.

; ======================================================================
; CODE 0x505a..0x50ae  (84 bytes)
; ======================================================================



; ----------------------------------------------------------------------
; NEMESIS LOOKS FOR ANOTHER KONAMI CARTRIDGE IN THE OTHER SLOTS
; At boot, INIT calls here and the cartridge starts looking at the
; machine's other slots and subslots with RDSLT, reading SIX bytes
; backwards from 0xBFFF and comparing them with the ones at 0x50AE.
; Those six bytes (AC 81 91 06 40 AA read in memory order) are not just
; any number: they are the END OF THE HIDDEN KONAMI MARK of another
; cartridge, the same one Nemesis carries at the end of its bank 3.
; Decoded with the house code: 0xAA closes it, 0x40 is the catalogue
; number (RC-740), 0x06 says the title has six characters, and the three
; being compared are, read the right way round, TU I N: ツイン, the
; start of ツインビー. In other words, Nemesis is looking for TwinBee
; (Konami, RC-740).
; If it finds it, 0xF0F4 stays at one, and with that the game loads extra
; graphics: the block at 0x9963 in 0x428A and the entries at 0x938E and
; 0x939B in 0x4326.
; ----------------------------------------------------------------------
find_other_cartridge:		; Walks slots 0, 0x80, 0x84, 0x88 and 0x8C looking for Konami's RC-740 mark
	xor a			;505a
	ld (0f0f4h),a		;505b   ; 0xF0F4 to zero: no companion for now
	ld c,000h		;505e   ; Slot 0 and the four subslots of slot 3
	call try_four_subslots		;5060
	ld c,080h		;5063
	call try_four_subslots		;5065
	ld c,084h		;5068
	call try_four_subslots		;506a
	ld c,088h		;506d
	call try_four_subslots		;506f
	ld c,08ch		;5072
	call try_four_subslots		;5074
	ret			;5077
try_four_subslots:		; Tries that slot and the next three; as soon as one matches, the search stops
	ld a,(0f0f4h)		;5078   ; If it was already found, the search does not go on
	and a			;507b
	ret nz			;507c
	ld b,004h		;507d   ; Four subslots
try_one_subslot:		; Tries that subslot and moves on to the next one
	push bc			;507f   ; Four subslots
	call compare_mark		;5080
	pop bc			;5083
	ret z			;5084
	inc c			;5085   ; The next one
	djnz try_one_subslot		;5086
	xor a			;5088
	ld (0f0f4h),a		;5089
	ret			;508c
compare_mark:		; Reads six bytes backwards from 0xBFFF in that slot and compares them with the ones at 0x50AE
	ld hl,0bfffh		;508d   ; Six bytes are read from the end of page 2 of ANOTHER slot, backwards.
	ld de,050aeh		;5090   ; And they are compared with the six at 0x50AE, which are the hidden Konami mark of another cartridge.
	ld b,006h		;5093   ; Six bytes
L_5095:
	push bc			;5095
	push hl			;5096
	push de			;5097
	ld a,c			;5098
	call 0000ch		;5099   ; BIOS RDSLT - Reads the value of an address in another slot | RDSLT: read an address from the slot A says, without switching slots.
	pop de			;509c
	pop hl			;509d
	pop bc			;509e
	ex de,hl			;509f
	cp (hl)			;50a0
	ex de,hl			;50a1
	ret nz			;50a2   ; As soon as one does not match, it gives up.
	inc de			;50a3   ; One goes up and the other goes down: the mark is written backwards
	dec hl			;50a4
	djnz L_5095		;50a5
	ld a,001h		;50a7   ; If all six match, 0xF0F4 = 1, and that switches on extra graphics.
	ld (0f0f4h),a		;50a9
	xor a			;50ac
	ret			;50ad

; ----------------------------------------------------------------------
; DATA rc740_mark: The six bytes 0x508D looks for in the other slots: AC 81 91
;   06 40 AA. They are the end of a hidden Konami mark: 0xAA closes it, 0x40
;   is the RC-740, 0x06 the length of the title, and AC 81 91 are, read the
;   right way round, TU I N (ツイン), that is, TwinBee.
;   0x50ae..0x50b4  (6 bytes)
DATA_rc740_mark:
	defb 0aah,040h,006h,091h,081h,0ach	; 50ae

; ======================================================================
; CODE 0x50b4..0x5163  (175 bytes)
; ======================================================================


clear_typing_state:		; 0xE1E0 to zero and the eight bytes at 0xE1E8 behind it
	push hl			;50b4
	push bc			;50b5
	ld hl,00000h		;50b6
	ld (0e1e0h),hl		;50b9
	ld hl,0e1e8h		;50bc
	ld b,008h		;50bf   ; Eight bytes
L_50C1:
	ld (hl),000h		;50c1   ; Eight bytes to zero
	inc hl			;50c3
	djnz L_50C1		;50c4
	pop bc			;50c6
	pop hl			;50c7
	ret			;50c8

; ----------------------------------------------------------------------
; THE CHEATS TYPED ON THE KEYBOARD, WHILE PAUSED
; This is NOT read while playing: 0x4518 only calls here when bit 0 of
; 0xE10B is set, that is, with the game PAUSED. You pause with the GRAPH
; key (row 6, bit 5, at 0x44F6), type, and on unpausing the game carries
; on. On entering pause, 0x50B4 erases whatever was typed before.
; Each new key is stored in 0xE1E8, up to eight, and on pressing RETURN
; what was typed is compared against the words at 0x51BF. What is in ROM:
; HYPER    only the first time (0xE06E), and jumps to 0xA0D8:
; EVERYTHING at once
; LASER    -> 0xA101      MISSILE -> 0xA106
; SHIELD   -> 0xA0E9      DOUBLE  -> 0xA10B
; OPTION   -> 0xA110      DOWN    -> 0xA0FA, which takes away
; BAKA and AHO (fool and idiot in Japanese) give NOTHING: they fall
; into 0x5127, which zeroes the lives, the flag and the two joystick
; flags.
; And on top of that each stage has ITS own woman's name (MOMOKO, CHIE,
; AKEMI, SYUKO, CHIAKI, NORIKO, SATOE, YASUKO, KINUYO, HISAE, MIYUKI,
; YOHKO), which the table at 0x5163 hands out by stage: getting right
; the one for the stage you are on sets 0xE071 to one and jumps to 0xA0D8.
; The six prizes are only given if 0xE071 is still at zero, so the name
; and the words get in each other's way.
; MEASURED IN openMSX with tools/omsx_cheats.tcl, not deduced: paused,
; 0xE1E8 fills with 4F 50 54 49 4F 4E (OPTION) and on pressing RETURN
; 0xE20B goes from 00 to 02, the two options. With BAKA, the lives at
; 0xE060 go from 02 to 00 and the 0xE05F flag goes off.
; ----------------------------------------------------------------------
check_typed_keys:		; Reads the keyboard and, on RETURN, compares what was typed against the cheats; each one jumps to its own routine in bank 3
	ld a,(0e200h)		;50c9   ; With 0xE200 negative there is no ship, and no cheats
	and a			;50cc
	ret m			;50cd
	call which_key_is_pressed		;50ce   ; Which key is being pressed
	and a			;50d1
	ret z			;50d2
	ld hl,0e1e1h		;50d3   ; 0xE1E1 keeps the previous one: only a new key counts
	cp (hl)			;50d6
	ret z			;50d7
	ld (hl),a			;50d8
	ld c,a			;50d9
	cp 00dh		;50da   ; 0x0D is RETURN: until it is pressed, keys are just written down
	jp nz,record_key		;50dc
	ld hl,clear_typing_state		;50df   ; 0x50B4 is pushed: whatever happens, what was typed is erased on the way out
	push hl			;50e2
	call compare_hyper		;50e3   ; HYPER
	jr nc,cheat_hyper		;50e6
	call compare_baka		;50e8   ; BAKA...
	jr nc,punish_insult		;50eb
	call compare_aho		;50ed   ; ...and AHO: both of them punish
	jr nc,punish_insult		;50f0
	ld a,(0e071h)		;50f2   ; With 0xE071 already set no other prize is accepted
	and a			;50f5
	ret nz			;50f6
	call compare_stage_name		;50f7   ; The woman's name that belongs to this stage
	jp nc,cheat_stage_name		;50fa
	ld a,(0e200h)		;50fd
	and a			;5100
	ret m			;5101
	call compare_missile		;5102   ; MISSILE
	jp nc,0a106h		;5105
	call compare_laser		;5108   ; LASER
	jp nc,0a101h		;510b
	call compare_shield		;510e   ; SHIELD
	jp nc,0a0e9h		;5111
	call compare_double		;5114   ; DOUBLE
	jp nc,0a10bh		;5117
	call compare_down		;511a   ; DOWN
	jp nc,0a0fah		;511d
	call compare_option		;5120   ; OPTION
	jp nc,0a110h		;5123
	ret			;5126
punish_insult:		; BAKA and AHO end up here: lives, flag and joystick flags to zero
	xor a			;5127   ; Lives, flag and the two joystick flags
	ld (0e060h),a		;5128
	ld (0e05fh),a		;512b
	ld (0e044h),a		;512e
	ld (0e047h),a		;5131
	ret			;5134
cheat_hyper:		; HYPER only works once per game, and 0xE06E keeps track of it
	ld hl,0e06eh		;5135   ; 0xE06E: HYPER only works once per game
	ld a,(hl)			;5138
	and a			;5139
	ret nz			;513a
	inc (hl)			;513b
	jp 0a0d8h		;513c
cheat_stage_name:		; The stage's name guessed right: 0xE071 to one and off to bank 3
	ld a,001h		;513f
	ld (0e071h),a		;5141
	jp 0a0d8h		;5144
record_key:		; Stores the new keys in 0xE1E8, up to eight
	ld hl,0e1e0h		;5147
	ld a,(hl)			;514a
	cp 008h		;514b   ; Eight letters at most
	ret nc			;514d
	inc (hl)			;514e
	ld hl,0e1e8h		;514f
	call add_a_to_hl		;5152
	ld (hl),c			;5155
	ret			;5156
compare_stage_name:		; Takes from the table at 0x5163 the name that belongs to this stage and compares it
	ld hl,05163h		;5157
	ld a,(0e061h)		;515a
	dec a			;515d
	call get_word		;515e
	jr $+80		;5161

; ----------------------------------------------------------------------
; DATA texts_per_stage: Fourteen words that 0x5157 indexes with the stage
;   minus one: where the name typed on each stage starts (0x51F6, 0x51FD,
;   0x5202, ...).
;   0x5163..0x517f  (28 bytes)
DATA_texts_per_stage:
	defw 051f6h,051fdh	; 5163
	defw 05202h,05208h	; 5167
	defw 0520eh,05215h	; 516b
	defw 0521ch,05222h	; 516f
	defw 05229h,05230h	; 5173
	defw 05236h,0523dh	; 5177
	defw 0523dh,0523dh	; 517b

; ======================================================================
; CODE 0x517f..0x51bf  (64 bytes)
; ======================================================================


compare_baka:
	ld de,051c5h		;517f   ; BAKA
	jr compare_word		;5182
compare_aho:
	ld de,051cah		;5184   ; AHO
	jr compare_word		;5187
compare_laser:
	ld de,051ceh		;5189   ; LASER
	jr prize_hit		;518c
compare_shield:
	ld de,051dch		;518e   ; SHIELD
	jr prize_hit		;5191
compare_down:
	ld de,051f1h		;5193   ; DOWN
	jr prize_hit		;5196
compare_option:
	ld de,051e3h		;5198   ; OPTION
	jr prize_hit		;519b
compare_double:
	ld de,051eah		;519d   ; DOUBLE
	jr prize_hit		;51a0
compare_missile:
	ld de,051d4h		;51a2   ; MISSILE
prize_hit:		; If the word matches, raises 0xE071 so that another prize cannot be chained
	call compare_word		;51a5
	ret c			;51a8
	ld hl,0e071h		;51a9   ; 0xE071 goes up: no other prize is accepted on this stage
	inc (hl)			;51ac
	ret			;51ad
compare_hyper:
	ld de,051bfh		;51ae   ; HYPER
compare_word:		; Compares what was typed in 0xE1E8 with the word at DE; 0x0D ends it, and it exits without carry if it matches
	ld hl,0e1e8h		;51b1
L_51B4:
	ld a,(de)			;51b4
	cp 00dh		;51b5   ; The 0x0D separates one word from the next
	ret z			;51b7
	cp (hl)			;51b8
	inc de			;51b9
	inc hl			;51ba
	jr z,L_51B4		;51bb
	scf			;51bd   ; Carry set: no match
	ret			;51be

; ----------------------------------------------------------------------
; DATA texts: Strings separated by 0x0D: HYPER, BAKA, AHO, LASER, MISSILE,
;   SHIELD, OPTION, DOUBLE, DOWN, and then the names that come by default in
;   the high score table: MOMOKO, CHIE, AKEMI, SYUKO, CHIAKI, NORIKO, SATOE,
;   YASUKO, KINUYO, HISAE, MIYUKI, YOHKO.
;   0x51bf..0x5243  (132 bytes)
DATA_texts:
	defb 048h,059h,050h,045h,052h,00dh,042h,041h,04bh,041h,00dh,041h,048h,04fh,00dh,04ch	; 51bf  HYPER.BAKA.AHO.L
	defb 041h,053h,045h,052h,00dh,04dh,049h,053h,053h,049h,04ch,045h,00dh,053h,048h,049h	; 51cf  ASER.MISSILE.SHI
	defb 045h,04ch,044h,00dh,04fh,050h,054h,049h,04fh,04eh,00dh,044h,04fh,055h,042h,04ch	; 51df  ELD.OPTION.DOUBL
	defb 045h,00dh,044h,04fh,057h,04eh,00dh,04dh,04fh,04dh,04fh,04bh,04fh,00dh,043h,048h	; 51ef  E.DOWN.MOMOKO.CH
	defb 049h,045h,00dh,041h,04bh,045h,04dh,049h,00dh,053h,059h,055h,04bh,04fh,00dh,043h	; 51ff  IE.AKEMI.SYUKO.C
	defb 048h,049h,041h,04bh,049h,00dh,04eh,04fh,052h,049h,04bh,04fh,00dh,053h,041h,054h	; 520f  HIAKI.NORIKO.SAT
	defb 04fh,045h,00dh,059h,041h,053h,055h,04bh,04fh,00dh,04bh,049h,04eh,055h,059h,04fh	; 521f  OE.YASUKO.KINUYO
	defb 00dh,048h,049h,053h,041h,045h,00dh,04dh,049h,059h,055h,04bh,049h,00dh,059h,04fh	; 522f  .HISAE.MIYUKI.YO
	defb 048h,04bh,04fh,00dh	; 523f

; ======================================================================
; CODE 0x5243..0x526b  (40 bytes)
; ======================================================================


which_key_is_pressed:		; Walks the eight keyboard rows with SNSMAT and returns the character of the first key pressed
	ld b,008h		;5243
	ld e,000h		;5245
L_5247:
	ld a,e			;5247
	call 00141h		;5248   ; BIOS SNSMAT - Returns the value of the specified line from the keyboard matrix | SNSMAT: keyboard row E
	cpl			;524b   ; A cpl: on the keyboard a pressed key is a zero
	and a			;524c
	jr nz,L_5257		;524d
	inc e			;524f
	djnz L_5247		;5250   ; Eight rows
	xor a			;5252
	ld (0e1e1h),a		;5253   ; With nothing pressed, 0xE1E1 to zero
	ret			;5256
L_5257:
	ld b,a			;5257
	ld a,e			;5258
	add a,a			;5259   ; The row times eight: eight keys per row
	add a,a			;525a
	add a,a			;525b
	ld hl,0526bh		;525c
	call add_a_to_hl		;525f
	ld a,b			;5262
L_5263:
	rra			;5263   ; It looks for the set bit, which is the key
	jr c,L_5269		;5264
	inc hl			;5266
	jr L_5263		;5267
L_5269:
	ld a,(hl)			;5269
	ret			;526a

; ----------------------------------------------------------------------
; DATA alphabet: The characters that can be chosen when entering the name, in
;   the order of the grid: 0123456789-^ and then @[;:],./_ and the 26 letters.
;   Indexed by 0x525C.
;   0x526b..0x52b3  (72 bytes)
DATA_alphabet:
	defb 030h,031h,032h,033h,034h,035h,036h,037h,038h,039h,02dh,05eh	; 526b  0123456789-^
	defb 009h,040h,05bh,03bh,03ah,05dh,02ch,02eh,02fh,05fh,041h,042h	; 5277  .@[;:],./_AB
	defb 043h,044h,045h,046h,047h,048h,049h,04ah,04bh,04ch,04dh,04eh	; 5283  CDEFGHIJKLMN
	defb 04fh,050h,051h,052h,053h,054h,055h,056h,057h,058h,059h,05ah	; 528f  OPQRSTUVWXYZ
	defb 000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h	; 529b  ............
	defb 000h,000h,000h,00dh,000h,000h,000h,000h,000h,000h,000h,000h	; 52a7  ............

; ======================================================================
; CODE 0x52b3..0x52c7  (20 bytes)
; ======================================================================


state_machine:		; Eight states, dispatched by the table at 0x52C7.
	ld hl,0e003h		;52b3   ; 0xE003 counts the runs of the interrupt.
	inc (hl)			;52b6
	ld hl,05506h		;52b7   ; This is the address the state is going to return to...
	ld bc,(0e000h)		;52ba
	ld a,c			;52be
	cp 003h		;52bf
	jr nc,L_52C4		;52c1
	push hl			;52c3   ; ...and it is pushed onto the stack ONLY if 0xE000 is less than 3.
L_52C4:
	call dispatcher		;52c4   ; Eight states, and the table goes right here behind.

; ----------------------------------------------------------------------
; DATA state_table: Eight words right behind the `call 0x4067` at 0x52C4: the
;   game's eight states (0x52D7, 0x5308, 0x5312, 0x537D, 0x53B1, 0x5464,
;   0x546F, 0x549A).
;   0x52c7..0x52d7  (16 bytes)
DATA_state_table:
	defw 052d7h,05308h	; 52c7  -> state_0 state_1
	defw 05312h,0537dh	; 52cb  -> state_2 state_3
	defw 053b1h,05464h	; 52cf  -> state_4 state_5
	defw 0546fh,0549ah	; 52d3  -> state_6 state_7

; ======================================================================
; CODE 0x52d7..0x5588  (689 bytes)
; ======================================================================


state_0:		; Three substates: the message at 0x57BD, the 0xE004 wait and building the title screen
	djnz L_52EC		;52d7   ; To substate 1 if it is not 0
	ld a,(0e003h)		;52d9
	rra			;52dc
	ret nc			;52dd
	call raise_logo		;52de
	ret nz			;52e1
	ld de,057bdh		;52e2
	call decompress_with_destination		;52e5
	xor a			;52e8
	jp L_5375		;52e9
L_52EC:
	djnz L_52FA		;52ec   ; To substate 2 if it is not 1
	ld hl,0e004h		;52ee   ; 0xE004: the frames of waiting left
	dec (hl)			;52f1
	ret nz			;52f2
	call write_title_panel		;52f3   ; And the title screen is built
	xor a			;52f6
	jp L_53A1		;52f7
L_52FA:
	call program_vdp		;52fa   ; The wipe, the clean screen and the score
	call clear_screen		;52fd
	call load_scoreboard		;5300
	call start_logo_curtain		;5303
	jr next_substate		;5306
state_1:		; Runs 0xE004 down and goes to the intro
	ld hl,0e004h		;5308
	dec (hl)			;530b
	jp nz,blink_selection		;530c
	jp wait_thirty_two_then_state		;530f
state_2:		; Maps banks 9 and 10 for one call, and splits into four substates
	djnz state_2_sub1		;5312
	di			;5314   ; Banks 9 and 10, which are the intro ones
	ld a,009h		;5315
	ld (08000h),a		;5317
	ld (0f0f2h),a		;531a
	ei			;531d
	di			;531e
	ld a,00ah		;531f
	ld (0a000h),a		;5321
	ld (0f0f3h),a		;5324
	ei			;5327
	call 0a88dh		;5328
	di			;532b   ; And 2 and 3 restored
	ld a,002h		;532c
	ld (08000h),a		;532e
	ld (0f0f2h),a		;5331
	ei			;5334
	di			;5335
	ld a,003h		;5336
	ld (0a000h),a		;5338
	ld (0f0f3h),a		;533b
	ei			;533e
	call upload_sprites_rotating		;533f
	call 0bdd2h		;5342
	ld a,(0e012h)		;5345   ; While the 0xE012 channel is sounding, it waits
	and a			;5348
	ret nz			;5349
	jr wait_thirty_two		;534a
state_2_sub1:		; Waits for the joystick and starts the thing at 0x5C88
	djnz state_2_sub2		;534c
	call lower_curtain		;534e   ; With the joystick untouched, it exits through p
	ret p			;5351   ; With the joystick untouched it exits through p
	call start_demo		;5352
	jr next_substate		;5355
state_2_sub2:		; Waits for the joystick and, if there is no flag in 0xE05F, goes back to state 0
	djnz state_2_sub3		;5357
	call run_demo		;5359   ; One step of the demo
	ld a,(0e05fh)		;535c
	or a			;535f
	ret nz			;5360
back_to_state_0:		; State 0, substate 0 and 0x20 frames of waiting
	xor a			;5361
