program_vdp:		; The eight values at 0x575A to registers 0 to 7, with WRTVDP
	ld hl,0575ah		;5749
	ld d,008h		;574c   ; Eight registers
	ld c,000h		;574e
L_5750:
	ld b,(hl)			;5750
	call 00047h		;5751   ; BIOS WRTVDP - Writes data in the VDP-register
	inc hl			;5754
	inc c			;5755
	dec d			;5756
	jr nz,L_5750		;5757
	ret			;5759

; ----------------------------------------------------------------------
