just_pressed:		; Saves the current state and, with an xor and an and, leaves in the next byte only what has just gone down
	ld c,(hl)			;576d   ; What has changed and is set: what was just pressed
	ld (hl),a			;576e
	xor c			;576f
	and (hl)			;5770
	dec hl			;5771
	ld (hl),a			;5772
	ret			;5773
