; ----------------------------------------------------------------------
; THE SAME CARTRIDGE IS CALLED GRADIUS OR NEMESIS DEPENDING ON THE MACHINE
; Here is the reason this game has two names. The cartridge reads 0x002B
; of the BIOS and keeps the low nibble, which is the machine's character
; set: at zero, Japanese. And with that it picks which of the TWO logos
; it writes on row 4: the one at 0x9BCB or the one at 0x9B3F, five rows
; of 28 characters each, both in bank 9 and right next to each other.
; Drawn from the ROM (decompressing their patterns from 0x9C57 and their
; colours from 0x9EAB and painting the panel) you can read what they
; say: the Japanese machine's one says GRADIUS and the other NEMESIS.
; They are not two versions of the cartridge: it is the SAME binary, with
; both titles inside.
; It is the same split by country that 0x4C42 uses for the ending message.
; ----------------------------------------------------------------------
	ld a,(0002bh)		;5b8e   ; The low nibble of 0x002B: the character set. At zero, Japanese
	and 00fh		;5b91
	ld de,09bcbh		;5b93   ; The Japanese panel...
	jr z,L_5B9B		;5b96
	ld de,09b3fh		;5b98   ; ...and the one for the other machines
L_5B9B:
	ld hl,03882h		;5b9b   ; Row 4, column 2
	ld b,005h		;5b9e   ; Five rows
L_5BA0:
	push bc			;5ba0
	call set_vram_write		;5ba1
	ld b,01ch		;5ba4   ; Twenty-eight characters per row
L_5BA6:
	ld a,(de)			;5ba6   ; Twenty-eight characters, through the data port
	inc de			;5ba7
	exx			;5ba8
	out (c),a		;5ba9
	exx			;5bab
	djnz L_5BA6		;5bac
	ld a,020h		;5bae   ; 0x20: the row below
	call add_a_to_hl		;5bb0   ; 0x20: the row below
	pop bc			;5bb3
	djnz L_5BA0		;5bb4
	di			;5bb6
	ld a,002h		;5bb7
	ld (08000h),a		;5bb9
	ld (0f0f2h),a		;5bbc
	ei			;5bbf
	di			;5bc0
	ld a,003h		;5bc1
	ld (0a000h),a		;5bc3
	ld (0f0f3h),a		;5bc6
	ei			;5bc9
	ld de,057ebh		;5bca   ; And on top, the two messages at 0x57EB
	call write_characters		;5bcd
	jp write_characters		;5bd0
blink_selection:		; A bit of 0xE004 turns off and on the message of the option selected in the intro
	ld hl,0e004h		;5bd3
	bit 3,(hl)		;5bd6   ; Bit 3 of the counter: on and off
	ld c,0ffh		;5bd8
	jr nz,L_5BDD		;5bda
	inc c			;5bdc
L_5BDD:
	ld hl,03a2ah		;5bdd   ; Row 17, column 10, and the one 0x40 further down
	ld de,03a6ah		;5be0
	ld a,(0e052h)		;5be3   ; 0xE052 says which of the two is selected
	or a			;5be6
	jr z,L_5BEA		;5be7
	ex de,hl			;5be9
L_5BEA:
	push de			;5bea
	call L_5BF1		;5beb
	pop hl			;5bee
	ld c,000h		;5bef
L_5BF1:
	ld de,0581dh		;5bf1
	jp L_49A0		;5bf4

