; ----------------------------------------------------------------------
; THE DEMO PLAYS ITSELF BY READING A RECORDING OF THE JOYSTICK
; The demo is not played by any clever machine: it is a RECORDING. In bank
; 12 there is, per stage, a list of pairs [how many frames][what the
; joystick reads], and 0x5CDA reads through it: 0xE00B counts the frames
; left and 0xE00C holds the joystick value, which 0x5CCF puts in 0xE009
; (the same byte where 0x5767 leaves what it reads from the real
; joystick), as well as turning on bit 4, which is fire. So the demo ship
; ALWAYS fires and moves the way the tape says.
; And it starts fully powered: 0x5CB8 calls 0xA0D8, which is the same
; thing the HYPER cheat gives.
; ----------------------------------------------------------------------
start_demo:		; Picks the stage that is due (0xE006 wraps at eight), sets it up with all the power-ups and leaves it ready to play itself
	xor a			;5c88
	ld (0e009h),a		;5c89
	ld (0e007h),a		;5c8c
	inc a			;5c8f
	ld (0e05fh),a		;5c90   ; 0xE05F to one: the flag that says a demo is running
	ld hl,0e006h		;5c93   ; 0xE006 holds which stage the demo is on
	ld a,(hl)			;5c96
	ld (0e061h),a		;5c97
	inc a			;5c9a
	cp 009h		;5c9b   ; Eight stages and back to the first
	jr c,L_5CA1		;5c9d
	ld a,001h		;5c9f
L_5CA1:
	ld (hl),a			;5ca1
	ld hl,00020h		;5ca2   ; 0x20 of distance covered
	ld (0e063h),hl		;5ca5
	ld hl,00001h		;5ca8   ; 0xE00B to one: the first step of the recording goes in straight away
	ld (0e00bh),hl		;5cab
	xor a			;5cae
	ld (0e00dh),a		;5caf
	ld (0e06ah),a		;5cb2
	call set_up_due_stage		;5cb5
	call 0a0d8h		;5cb8   ; And all the power-ups at once, like the HYPER cheat
	jp write_captions		;5cbb
run_demo:		; While it lasts, takes the joystick value from the recording and passes it to the game as if someone had pressed it
	ld a,(0e064h)		;5cbe   ; With 0xE064 set, the demo is cut short
	and a			;5cc1
	jr z,L_5CC9		;5cc2
	xor a			;5cc4
	ld (0e05fh),a		;5cc5
	ret			;5cc8
L_5CC9:
	ld hl,0e00bh		;5cc9   ; 0xE00B: the frames left in this step
	dec (hl)			;5ccc
	jr z,next_recording_step		;5ccd
feed_recorded_controller:		; The recorded value goes to 0xE009, with bit 4 (fire) always set
	ld a,(0e00ch)		;5ccf
	or 010h		;5cd2   ; Bit 4: in the demo it fires non-stop
	ld (0e009h),a		;5cd4
	jp check_pause_key		;5cd7
next_recording_step:		; Maps banks 11 and 12, takes the next pair from the stage's list and leaves it in 0xE00B and 0xE00C
	inc hl			;5cda
	inc hl			;5cdb
	ld c,(hl)			;5cdc   ; 0xE00D says which pair it is on
	inc (hl)			;5cdd
	di			;5cde   ; Banks 11 and 12: the recordings are there
	ld a,00bh		;5cdf
	ld (08000h),a		;5ce1
	ld (0f0f2h),a		;5ce4
	ei			;5ce7
	di			;5ce8
	ld a,00ch		;5ce9
	ld (0a000h),a		;5ceb
	ld (0f0f3h),a		;5cee
	ei			;5cf1
	ld a,(0e061h)		;5cf2
	ld hl,l5d1dh		;5cf5   ; The table at 0x5D1D, indexed by the stage
	call get_word		;5cf8
	ld l,c			;5cfb
	ld h,000h		;5cfc
	add hl,hl			;5cfe   ; Times two: each step is two bytes
	add hl,de			;5cff
	ld a,(hl)			;5d00   ; The first, the frames it lasts
	ld (0e00bh),a		;5d01
	inc hl			;5d04
	ld a,(hl)			;5d05   ; And the second, what the joystick reads
	ld (0e00ch),a		;5d06
	di			;5d09   ; 2 and 3 restored
	ld a,002h		;5d0a
	ld (08000h),a		;5d0c
	ld (0f0f2h),a		;5d0f
	ei			;5d12
	di			;5d13
	ld a,003h		;5d14
	ld (0a000h),a		;5d16
	ld (0f0f3h),a		;5d19
	ei			;5d1c
L_5D1D:
	jr feed_recorded_controller		;5d1d

