	cp 010h		;5e44   ; Past sixteen, the animation is over
	jr nc,$+31		;5e46
	rra			;5e48   ; Skipping one bit: each drawing lasts two frames
	and 006h		;5e49
	ld hl,05e5dh		;5e4b
	call add_a_to_hl		;5e4e
	ld a,(hl)			;5e51
	ld (ix+00ch),a		;5e52   ; The character in byte 12 and the colour in 13
	inc hl			;5e55
	ld a,(hl)			;5e56
	ld (ix+00dh),a		;5e57
	jp 09251h		;5e5a

; ----------------------------------------------------------------------
; DATA characters_of_5E4B: Eight bytes that 0x5E4B indexes with (A AND 6) and
;   puts in (IX+0x0C).
;   0x5e5d..0x5e65  (8 bytes)
DATA_characters_of_5E4B:
	defb 078h,00fh,07ch,009h,080h,006h,084h,00dh	; 5e5d  x.|.....

; ======================================================================
; CODE 0x5e65..0x5ee3  (126 bytes)
; ======================================================================


object_to_explosion:		; Turns the object into an explosion: gives it type 0x12 or 0x13 and its character, and snaps its X and Y to the grid
	ld a,(ix+011h)		;5e65   ; Byte 17 says whether the object belongs to a group
	and a			;5e68
	jr z,L_5E88		;5e69
	ld a,(ix+012h)		;5e6b
	call find_group		;5e6e   ; The group is looked up in the table at 0xE900
	jp c,turn_off_object		;5e71
	ld a,(hl)			;5e74
	inc l			;5e75
	inc l			;5e76
	dec (hl)			;5e77   ; The group's count goes down; until it reaches zero, it does not blow up
	jp nz,turn_off_object		;5e78
	dec l			;5e7b
	dec l			;5e7c
	ld (hl),000h		;5e7d
	and 007h		;5e7f
	ld a,012h		;5e81
	jr nz,L_5E95		;5e83
	inc a			;5e85
	jr L_5E95		;5e86
L_5E88:
	ld a,(ix+00eh)		;5e88   ; Without a group, byte 14 decides
	and a			;5e8b
	jp z,turn_off_object		;5e8c
	dec a			;5e8f
	ld a,012h		;5e90
	jr z,L_5E95		;5e92
	inc a			;5e94
L_5E95:
	ld (ix+000h),a		;5e95   ; Type 0x12 or 0x13: the two explosion sizes
	add a,00fh		;5e98
	ld (ix+00ch),a		;5e9a
	ld (ix+00bh),001h		;5e9d   ; Byte 11 to one: it is drawn with characters
	ld (ix+01bh),001h		;5ea1
	ld a,(ix+004h)		;5ea5   ; The Y, snapped to eight, plus four
	and 0f8h		;5ea8
	add a,004h		;5eaa
	ld (ix+004h),a		;5eac
	ld a,(ix+006h)		;5eaf   ; And the X, snapped to eight
	and 0f8h		;5eb2
	ld (ix+006h),a		;5eb4
	jp 09251h		;5eb7
find_group:		; Walks the four three-byte entries at 0xE900 looking for group A; exits with carry if it is not there
	ld hl,0e900h		;5eba
	ld b,004h		;5ebd   ; Four groups
L_5EBF:
	cp (hl)			;5ebf
	ret z			;5ec0
	inc l			;5ec1   ; Three bytes per group
	inc l			;5ec2
	inc l			;5ec3
	djnz L_5EBF		;5ec4
	scf			;5ec6
	ret			;5ec7
animate_four_characters:		; The first sixteen frames, a character from 0x5EE3 every four; after that, the object blows up
	ld a,(ix+002h)		;5ec8
	inc (ix+002h)		;5ecb
	cp 010h		;5ece   ; Past sixteen, on to exploding
	jr nc,object_to_explosion		;5ed0
	rra			;5ed2   ; Skipping two bits: each drawing lasts four frames
	rra			;5ed3
	and 003h		;5ed4
	ld hl,05ee3h		;5ed6
	call add_a_to_hl		;5ed9
	ld a,(hl)			;5edc
	ld (ix+00ch),a		;5edd
	jp 09251h		;5ee0

; ----------------------------------------------------------------------
; DATA characters_of_5ED6: Four bytes (0xF0, 0xF4, 0xF8, 0xFC) that 0x5ED6
;   indexes with (A AND 3).
;   0x5ee3..0x5ee7  (4 bytes)
DATA_characters_of_5ED6:
	defb 0f0h,0f4h,0f8h,0fch	; 5ee3

; ======================================================================
; CODE 0x5ee7..0x5f47  (96 bytes)
; ======================================================================


move_hatch_enemy:		; Every four frames changes drawing, moves with the screen and, when the ship crosses its row, turns
	ld a,(0e003h)		;5ee7
	and 003h		;5eea   ; One frame in four
	jr nz,L_5F00		;5eec
	inc (ix+002h)		;5eee
	ld a,(ix+002h)		;5ef1
	and 007h		;5ef4   ; Eight drawings, round and round
	ld hl,05f47h		;5ef6
	call add_a_to_hl		;5ef9
	ld a,(hl)			;5efc
	ld (ix+00ch),a		;5efd
L_5F00:
	ld a,(ix+001h)		;5f00
	and a			;5f03
	ret nz			;5f04
	ld a,(0e100h)		;5f05   ; On the steps with a new column, it moves eight points to the left
	and a			;5f08
	jr z,L_5F13		;5f09
	ld a,(ix+006h)		;5f0b
	sub 008h		;5f0e
	ld (ix+006h),a		;5f10
L_5F13:
	ld a,(0e204h)		;5f13   ; 0xE204 is the ship's row, and bit 7 of byte 8 the sign of its vertical speed
	bit 7,(ix+008h)		;5f16
	jr nz,L_5F22		;5f1a
	cp (ix+004h)		;5f1c
	ret nc			;5f1f
	jr enemy_turns		;5f20
L_5F22:
	cp (ix+004h)		;5f22
	ret c			;5f25
enemy_turns:		; Stops going up or down (the speed in bytes 7 and 8 to zero) and takes 0xFC00 horizontally: it launches itself at the ship
	inc (ix+001h)		;5f26
	xor a			;5f29
	ld (ix+007h),a		;5f2a
	ld (ix+008h),a		;5f2d
	ld hl,0fc00h		;5f30   ; 0xFC00 in bytes 9 and 10: four points per frame to the left
	ld (ix+009h),l		;5f33
	ld (ix+00ah),h		;5f36
	ld a,(0e066h)		;5f39   ; 0xE066 is the stages played: from the second loop onwards, it fires when it turns
	and a			;5f3c
	ret z			;5f3d
	ld e,(ix+004h)		;5f3e
	ld d,(ix+006h)		;5f41
	jp 06613h		;5f44

; ----------------------------------------------------------------------
; DATA animation_of_5EF6: Eight bytes (4,5,6,7,8,7,6,5) that 0x5EF6 indexes
;   with the counter (IX+2) AND 7: the back-and-forth of an animation.
;   0x5f47..0x5f4f  (8 bytes)
DATA_animation_of_5EF6:
	defb 004h,005h,006h,007h,008h,007h,006h,005h	; 5f47  ........

; ======================================================================
; CODE 0x5f4f..0x6000  (177 bytes)
; ======================================================================


check_map_collision:		; Passes the object's X and Y to bank 2, with a correction of eight depending on bit 0 of byte 8
	ld l,(ix+004h)		;5f4f
	ld h,(ix+006h)		;5f52
	bit 0,(ix+008h)		;5f55   ; Bit 0 of byte 8 says whether the Y has to be shifted
	jr nz,L_5F5F		;5f59
	ld a,008h		;5f5b
	add a,l			;5f5d
	ld l,a			;5f5e
L_5F5F:
	call 09857h		;5f5f
	ret nc			;5f62
	jp turn_off_object		;5f63
check_object_gone:		; Types 2 to 0x10 and 0x1B to 0x1D add their speed and, if they go off the screen, are turned off
	ld a,(ix+000h)		;5f66
	cp 002h		;5f69   ; Types 0 and 1 do not move this way
	ret c			;5f6b
	cp 01eh		;5f6c   ; And neither does 0x1E
	ret z			;5f6e
	cp 011h		;5f6f   ; Nor do 0x11 to 0x1A
	jr c,L_5F76		;5f71
	cp 01bh		;5f73
	ret c			;5f75
L_5F76:
	call add_speed		;5f76
	jr nc,turn_off_object		;5f79
	ret			;5f7b
add_speed:		; Adds the object's two 16-bit speeds to it and returns whether it is still inside the screen
	push ix		;5f7c
	pop hl			;5f7e
	inc l			;5f7f   ; Bytes 3 and 4: the 16-bit Y
	inc l			;5f80
	inc l			;5f81
	ld d,h			;5f82
	ld e,l			;5f83
	inc e			;5f84   ; And 7 and 8: its speed
	inc e			;5f85
	inc e			;5f86
	inc e			;5f87
	call add_word		;5f88
	call add_word		;5f8b
	ld a,(ix+004h)		;5f8e   ; Past Y 0xB0 or X 0xF9, the object is gone
	cp 0b0h		;5f91
	ret nc			;5f93
	ld a,(ix+006h)		;5f94
	cp 0f9h		;5f97
	ret			;5f99
add_word:		; Adds two bytes from DE onto the two at HL, with carry
	ld a,(de)			;5f9a   ; The low byte...
	add a,(hl)			;5f9b
	ld (hl),a			;5f9c
	inc l			;5f9d
	inc e			;5f9e
	ld a,(de)			;5f9f   ; ...and the high one with the carry
	adc a,(hl)			;5fa0
	ld (hl),a			;5fa1
	inc l			;5fa2
	inc e			;5fa3
	ret			;5fa4
turn_off_object:		; Frees the slot and lowers the count of live objects; if it was in a group, lowers the group's count too
	ld a,(ix+000h)		;5fa5
	cp 01eh		;5fa8   ; Type 0x1E takes up three slots
	jr z,turn_off_three_slots		;5faa
	ld hl,0e126h		;5fac   ; 0xE126 keeps the count of live objects
	dec (hl)			;5faf
	xor a			;5fb0
	ld (ix+000h),a		;5fb1
	ld (ix+01bh),a		;5fb4
	bit 0,(ix+011h)		;5fb7   ; Bit 0 of byte 17: it belongs to a group
	ret z			;5fbb   ; Bit 0 of byte 17: the object was in a group
	ld a,(ix+012h)		;5fbc
	call find_group		;5fbf   ; Its group is looked up in the table at 0xE900
	ret c			;5fc2
	inc l			;5fc3   ; The group's count goes down
	dec (hl)			;5fc4
	ret nz			;5fc5
	dec l			;5fc6
	ld (hl),000h		;5fc7   ; And on reaching zero, the group is closed
	ret			;5fc9
turn_off_three_slots:		; The big type 0x1E object takes up three consecutive slots: all three are turned off and the count drops by three
	ld hl,0e126h		;5fca
	dec (hl)			;5fcd
	dec (hl)			;5fce
	dec (hl)			;5fcf
	push ix		;5fd0
	pop iy		;5fd2
	ld de,00020h		;5fd4   ; Thirty-two bytes: the next slot
	ld b,003h		;5fd7   ; Three slots
	xor a			;5fd9
L_5FDA:
	ld (iy+000h),a		;5fda
	ld (iy+01bh),a		;5fdd
	add iy,de		;5fe0
	djnz L_5FDA		;5fe2
run_background_objects:		; Stage 5 has its own engine in bank 3; the others walk eight or two objects at 0xE700
	ld a,(0e061h)		;5fe4
	cp 005h		;5fe7   ; Stage 5 goes another way
	jp z,0b2aah		;5fe9
	ld ix,0e700h		;5fec
	ld a,(0e061h)		;5ff0
	cp 003h		;5ff3   ; Stage 3 has eight; the others, two
	ld b,008h		;5ff5
	jr z,L_5FFB		;5ff7
	ld b,002h		;5ff9
L_5FFB:
	push bc			;5ffb
	call 06008h		;5ffc
	pop bc			;5fff
